window.UNITS=[{"g":6,"u":1,"title":"My New School","vi":"Trường mới của em","lessons":[{"type":"v","title":"Types of school & School things – Đồ dùng học tập","words":[{"w":"lower secondary school","vi":"trường cấp 2 (THCS)","ex":"My brother goes to a {lower secondary school} near our house."},{"w":"boarding school","vi":"trường nội trú","ex":"Students live and study at a {boarding school}."},{"w":"international school","vi":"trường quốc tế","ex":"Many foreign students study at the {international school}."},{"w":"pencil case","vi":"hộp bút","ex":"I keep my pens in a {pencil case}."},{"w":"pen","vi":"bút mực","ex":"Can I borrow your {pen}?"},{"w":"notebook","vi":"quyển vở","ex":"Write the new words in your {notebook}."},{"w":"textbook","vi":"sách giáo khoa","ex":"Open your English {textbook} at page 10."},{"w":"pencil sharpener","vi":"cái gọt bút chì","ex":"My pencil is blunt. I need a {pencil sharpener}."},{"w":"compass","vi":"cái com-pa","ex":"We use a {compass} to draw circles."},{"w":"calculator","vi":"cái máy tính (bỏ túi)","ex":"You can't use a {calculator} in the maths test."},{"w":"rubber","vi":"cục tẩy","ex":"Can I use your {rubber}? I made a mistake."},{"w":"eraser","vi":"cục tẩy","ex":"I need an {eraser} to rub out this word."}]},{"type":"v","title":"Subjects & School activities – Các hoạt động ở trường (1/2)","words":[{"w":"maths","vi":"môn toán","ex":"We have {maths} on Monday and Friday."},{"w":"English","vi":"Tiếng Anh","ex":"{English} is my favourite subject."},{"w":"Vietnamese","vi":"Tiếng Việt","ex":"We read poems in our {Vietnamese} lessons."},{"w":"history","vi":"lịch sử","ex":"In {history}, we learn about the past."},{"w":"science","vi":"khoa học","ex":"We do experiments in {science} lessons."},{"w":"music","vi":"âm nhạc","ex":"We sing songs in {music} lessons."},{"w":"art","vi":"mỹ thuật","ex":"We draw pictures in {art} lessons."},{"w":"have new friends","vi":"có bạn mới","ex":"I {have new friends} at my new school."},{"w":"have school lunch","vi":"ăn trưa ở trường","ex":"We {have school lunch} at 11 o'clock."},{"w":"have lessons","vi":"có các tiết học","ex":"We {have lessons} from Monday to Friday."},{"w":"do exercises","vi":"làm bài tập","ex":"We {do exercises} in class."},{"w":"do homework","vi":"làm bài tập về nhà","ex":"I {do homework} every evening."},{"w":"do paintings","vi":"vẽ tranh","ex":"We {do paintings} in the art room."},{"w":"play football","vi":"chơi bóng đá","ex":"The boys {play football} in the playground."},{"w":"play music","vi":"chơi nhạc","ex":"My friends and I {play music} after school."}]},{"type":"v","title":"School activities – Các hoạt động ở trường (2/2)","words":[{"w":"study new words","vi":"học từ mới","ex":"I {study new words} every day."},{"w":"study in the library","vi":"học trong thư viện","ex":"We {study in the library} on Wednesday afternoon."},{"w":"grow flowers","vi":"trồng hoa","ex":"We {grow flowers} in the school garden."},{"w":"swim in the swimming pool","vi":"bơi ở bể bơi","ex":"We {swim in the swimming pool} on Saturdays."},{"w":"help classmates","vi":"giúp đỡ bạn cùng lớp","ex":"Good students {help classmates} with their homework."},{"w":"wear uniforms","vi":"mặc đồng phục","ex":"We {wear uniforms} at school."},{"w":"look smart","vi":"trông lịch sự","ex":"You {look smart} in your new uniform."}]},{"type":"g","title":"Present simple","vi":"Thì hiện tại đơn","notes":["Dùng để nói về thói quen (I get up at 6 a.m. every day.) và sự thật hiển nhiên (The Earth goes around the Sun.).","(+) S + V / V-s / V-es · (–) S + don't / doesn't + V · (?) Do / Does + S + V …?","Chủ ngữ số nhiều (I, you, we, they) dùng V nguyên mẫu / don't / Do; chủ ngữ số ít (he, she, it) dùng V-s/es / doesn't / Does.","Thêm -es sau động từ tận cùng là o, ch, s, x, sh, z: goes, watches, misses, fixes, washes.","Dấu hiệu: always, usually, often, sometimes, rarely, hardly, never (đứng trước động từ thường, sau \"be\"); once a week, twice a week, every day.","Phát âm -s/-es: /s/ sau âm th, p, k, f, t (thanks, stops); /ɪz/ sau x, s, ch, sh, z (watches, washes); /z/ sau các âm còn lại (listens, does)."],"items":[{"t":"gap","q":"They often ___ football after school. (play)","a":["play"]},{"t":"gap","q":"She always ___ TV in the evening. (watch)","a":["watches"]},{"t":"gap","q":"I ___ up early every Sunday. (not get)","a":["don't get","do not get"]},{"t":"gap","q":"Lucy ___ coffee. (not like)","a":["doesn't like","does not like"]},{"t":"gap","q":"___ you enjoy going swimming?","a":["Do"]},{"t":"gap","q":"___ she love collecting coins?","a":["Does"]},{"t":"gap","q":"My father ___ to work by bus. (go)","a":["goes"]},{"t":"gap","q":"The Earth ___ around the Sun. (go)","a":["goes"]},{"t":"gap","q":"We ___ English on Monday. (have)","a":["have"]},{"t":"gap","q":"He ___ his homework after dinner. (do)","a":["does"]},{"t":"mc","q":"My sister ___ her teeth twice a day.","o":["brush","brushs","brushes","brushing"],"a":["brushes"]},{"t":"mc","q":"___ your friends live near the school?","o":["Do","Does","Are","Is"],"a":["Do"]},{"t":"mc","q":"Tom ___ like fish.","o":["don't","doesn't","isn't","aren't"],"a":["doesn't"]},{"t":"mc","q":"I ___ late for school.","o":["never am","am never","never is","is never"],"a":["am never"]},{"t":"mc","q":"She ___ goes to the library on Saturdays.","o":["usually","usual","usualy","use"],"a":["usually"]},{"t":"mc","q":"Which word has the ending pronounced /ɪz/?","o":["watches","stops","listens","plays"],"a":["watches"]},{"t":"mc","q":"Which word has the ending pronounced /s/?","o":["thanks","does","listens","plays"],"a":["thanks"]},{"t":"mc","q":"We go swimming ___ a week.","o":["twice","two","second","double"],"a":["twice"]}]}]},{"g":6,"u":2,"title":"My House","vi":"Ngôi nhà của em","lessons":[{"type":"v","title":"Types of house & Rooms in a house – Các phòng trong nhà","words":[{"w":"villa","vi":"căn biệt thự","ex":"They live in a big {villa} by the sea."},{"w":"flat","vi":"căn hộ","ex":"We live in a small {flat} on the fifth floor."},{"w":"town house","vi":"nhà phố","ex":"My aunt lives in a {town house} in the city centre."},{"w":"country house","vi":"nhà ở quê","ex":"My grandparents have a {country house} with a big garden."},{"w":"stilt house","vi":"nhà sàn","ex":"Many people in the mountains live in a {stilt house}."},{"w":"hall","vi":"sảnh, hành lang","ex":"Leave your shoes in the {hall}."},{"w":"bedroom","vi":"phòng ngủ","ex":"My {bedroom} is small but tidy."},{"w":"living room","vi":"phòng khách","ex":"We watch TV in the {living room}."},{"w":"kitchen","vi":"phòng bếp","ex":"Mum is cooking in the {kitchen}."},{"w":"bathroom","vi":"phòng tắm","ex":"The {bathroom} is next to my bedroom."}]},{"type":"v","title":"Furniture – Nội thất (1/2)","words":[{"w":"television","vi":"ti vi","ex":"There is a big {television} in the living room."},{"w":"computer","vi":"máy tính","ex":"I do my homework on the {computer}."},{"w":"armchair","vi":"ghế bành","ex":"Grandpa is sitting in the {armchair}."},{"w":"lamp","vi":"đèn ngủ, đèn bàn","ex":"There is a {lamp} next to my bed."},{"w":"pillow","vi":"cái gối","ex":"I like a soft {pillow}."},{"w":"picture","vi":"bức tranh","ex":"There is a beautiful {picture} on the wall."},{"w":"clock","vi":"đồng hồ","ex":"The {clock} on the wall says seven o'clock."},{"w":"wardrobe","vi":"tủ quần áo","ex":"I keep my clothes in the {wardrobe}."}]},{"type":"v","title":"Furniture – Nội thất (2/2)","words":[{"w":"dishwasher","vi":"máy rửa bát","ex":"Put the dirty plates in the {dishwasher}."},{"w":"fridge","vi":"tủ lạnh","ex":"Put the milk in the {fridge}."},{"w":"cupboard","vi":"tủ chén bát","ex":"The cups are in the {cupboard}."},{"w":"sink","vi":"bồn rửa","ex":"Wash your hands in the {sink}."},{"w":"cooker","vi":"cái nồi, bếp nấu","ex":"Mum puts the soup on the {cooker}."},{"w":"shower","vi":"vòi sen","ex":"I have a {shower} every morning."},{"w":"chest of drawers","vi":"tủ nhiều ngăn kéo","ex":"My socks are in the {chest of drawers}."}]},{"type":"g","title":"There is / There are","vi":"Có …","notes":["There is + danh từ số ít / không đếm được: There is a lamp and a wardrobe in the bedroom.","There are + danh từ số nhiều: There are two cookers and a cupboard in the kitchen.","Có thể viết lại với \"have/has\": There is a kitchen in my house. = My house has a kitchen."],"items":[{"t":"gap","q":"___ a lamp and a wardrobe in the bedroom.","a":["There is","There's"]},{"t":"gap","q":"___ two cookers in the kitchen.","a":["There are"]},{"t":"gap","q":"There ___ three bedrooms in my house.","a":["are"]},{"t":"gap","q":"There ___ a big fridge in the kitchen.","a":["is"]},{"t":"gap","q":"___ there a sofa in the living room? – Yes, there is.","a":["Is"]},{"t":"gap","q":"There are two beds in my room. = My room ___ two beds.","a":["has"]},{"t":"mc","q":"There ___ some pictures on the wall.","o":["is","are","am","be"],"a":["are"]},{"t":"mc","q":"There ___ a clock in the hall.","o":["is","are","have","has"],"a":["is"]},{"t":"mc","q":"___ there any chairs in the kitchen?","o":["Are","Is","Do","Does"],"a":["Are"]},{"t":"mc","q":"There is a kitchen in my house. = My house ___ a kitchen.","o":["has","have","is","are"],"a":["has"]}]},{"type":"g","title":"Prepositions of place","vi":"Giới từ chỉ vị trí","notes":["in (ở trong): The cat is in the box. · on (ở trên): The book is on the table. · under (ở dưới): Your shoes are under the bed.","next to (bên cạnh): The cat is next to the sofa. · behind (phía sau): The cat is behind the dog. · in front of (phía trước): The dog is in front of the cat.","between … and … (ở giữa): The dog is between the lamp and the armchair."],"items":[{"t":"gap","q":"The cat is ___ the box. (ở trong)","a":["in"]},{"t":"gap","q":"The book is ___ the table. (ở trên)","a":["on"]},{"t":"gap","q":"Your shoes are ___ the bed. (ở dưới)","a":["under"]},{"t":"gap","q":"The dog is ___ the lamp and the armchair. (ở giữa)","a":["between"]},{"t":"gap","q":"The cat is ___ the dog. (phía sau)","a":["behind"]},{"t":"mc","q":"The dog is ___ the cat. (phía trước)","o":["in front of","behind","between","under"],"a":["in front of"]},{"t":"mc","q":"The cat is ___ the sofa. (bên cạnh)","o":["next to","in","on","between"],"a":["next to"]},{"t":"mc","q":"My school is ___ the bank and the post office.","o":["between","next","in front","under"],"a":["between"]}]},{"type":"g","title":"Possessive case","vi":"Sở hữu cách","notes":["Danh từ số ít & tên riêng + 's: This is Jenny's book. The cat's tail is long.","Danh từ số nhiều có -s + ': The students' classroom is big. This is my parents' house."],"items":[{"t":"gap","q":"This is ___ book. (Jenny)","a":["Jenny's"]},{"t":"gap","q":"The ___ tail is long. (cat)","a":["cat's"]},{"t":"gap","q":"This is my ___ house. (parents)","a":["parents'"]},{"t":"gap","q":"The ___ classroom is big and beautiful. (students)","a":["students'"]},{"t":"mc","q":"This is ___ bike.","o":["Nam's","Nams","Nams'","Nam"],"a":["Nam's"]},{"t":"mc","q":"The ___ toys are in the box. (các con chó)","o":["dogs'","dog's","dogs","dogs's"],"a":["dogs'"]},{"t":"mc","q":"My ___ car is red. (bố tôi)","o":["father's","fathers'","fathers","father"],"a":["father's"]}]}]},{"g":6,"u":3,"title":"My Friends","vi":"Bạn bè của em","lessons":[{"type":"v","title":"Hair descriptions – Miêu tả tóc","words":[{"w":"blonde hair","vi":"tóc vàng (sẫm)","ex":"My new friend has long {blonde hair}."},{"w":"fair hair","vi":"tóc vàng hoe (nhạt)","ex":"The baby has {fair hair} and blue eyes."},{"w":"curly hair","vi":"tóc xoăn","ex":"Mai has short {curly hair}."},{"w":"straight hair","vi":"tóc thẳng","ex":"Lan has long black {straight hair}."},{"w":"wavy hair","vi":"tóc gợn sóng","ex":"My mother has beautiful {wavy hair}."},{"w":"What does he look like?","vi":"Cậu ấy trông như thế nào? (hỏi ngoại hình)","ex":"\"{What does he look like?}\" – \"He has short hair and big eyes.\""}]},{"type":"v","title":"Personality adjectives – Tính từ miêu tả tính cách","words":[{"w":"confident","vi":"tự tin","ex":"She is {confident} when she speaks in front of the class."},{"w":"caring","vi":"quan tâm người khác","ex":"My sister is very {caring}; she always looks after me."},{"w":"active","vi":"năng động","ex":"Nam is {active}; he does many activities after school."},{"w":"careful","vi":"cẩn thận","ex":"Be {careful} and check your answers."},{"w":"creative","vi":"sáng tạo","ex":"Minh is {creative}; he always has new ideas."},{"w":"shy","vi":"nhút nhát","ex":"He is {shy}, so he doesn't talk much in class."},{"w":"kind","vi":"tốt bụng","ex":"She is {kind} and always helps her friends."},{"w":"helpful","vi":"hay giúp đỡ","ex":"My classmates are very {helpful}."},{"w":"clever","vi":"thông minh","ex":"Lan is {clever}; she learns quickly and easily."},{"w":"hard-working","vi":"chăm chỉ","ex":"He is {hard-working}; he always does his homework."},{"w":"funny","vi":"hài hước","ex":"My friend is {funny}; he makes people laugh."},{"w":"sporty","vi":"ưa thích thể thao","ex":"Tom is {sporty}; he plays football and tennis."},{"w":"What is she like?","vi":"Cô ấy là người thế nào? (hỏi tính cách)","ex":"\"{What is she like?}\" – \"She is kind and hard-working.\""}]},{"type":"g","title":"Present continuous","vi":"Thì hiện tại tiếp diễn","notes":["(+) S + am/is/are + V-ing · (–) S + am/is/are + not + V-ing · (?) Am/Is/Are + S + V-ing?","Dấu hiệu: now (bây giờ), right now (ngay bây giờ), at the moment / at present (hiện tại), today (hôm nay), dấu ! đầu câu (Look! Listen!).","Ví dụ: I am watching TV now. · Look! They are playing football. · He isn't sleeping now. · Are you doing your homework now? – Yes, I am. / No, I'm not."],"items":[{"t":"gap","q":"I ___ TV now. (watch)","a":["am watching","'m watching"]},{"t":"gap","q":"She ___ at the moment. (cook)","a":["is cooking","'s cooking"]},{"t":"gap","q":"Look! They ___ football. (play)","a":["are playing","'re playing"]},{"t":"gap","q":"I ___ at present. (not study)","a":["am not studying","'m not studying"]},{"t":"gap","q":"He ___ now. (not sleep)","a":["isn't sleeping","is not sleeping"]},{"t":"gap","q":"We ___ at the moment. (not eat)","a":["aren't eating","are not eating"]},{"t":"gap","q":"___ you doing your homework now?","a":["Are"]},{"t":"gap","q":"Is she singing at present? – Yes, she ___.","a":["is"]},{"t":"gap","q":"Listen! The birds ___. (sing)","a":["are singing"]},{"t":"mc","q":"Are they playing games at the moment? – No, they ___.","o":["aren't","isn't","don't","doesn't"],"a":["aren't"]},{"t":"mc","q":"My mother ___ in the kitchen now.","o":["is cooking","cooks","are cooking","cook"],"a":["is cooking"]},{"t":"mc","q":"___ you listening to me?","o":["Are","Do","Is","Does"],"a":["Are"]},{"t":"mc","q":"Which word is a signal for the present continuous?","o":["at the moment","every day","usually","once a week"],"a":["at the moment"]},{"t":"mc","q":"Look! The children ___ in the garden.","o":["are running","run","runs","is running"],"a":["are running"]}]}]},{"g":6,"u":4,"title":"My Neighbourhood","vi":"Khu phố của em","lessons":[{"type":"v","title":"Asking for and giving directions – Hỏi và chỉ đường","words":[{"w":"Let's","vi":"Hãy cùng …","ex":"{Let's} go to the cinema this evening."},{"w":"Shall we","vi":"Chúng ta sẽ … chứ?","ex":"{Shall we} visit the art gallery on Sunday?"},{"w":"Can you show me the way to","vi":"Bạn có thể chỉ cho tôi đường đến …","ex":"Excuse me. {Can you show me the way to} the railway station?"},{"w":"how to get to","vi":"cách để đến …","ex":"Can you tell me {how to get to} the post office?"},{"w":"near","vi":"gần","ex":"My house is {near} the school."},{"w":"far","vi":"xa","ex":"The museum is {far} from here."},{"w":"turn left","vi":"rẽ trái","ex":"{Turn left} at the traffic lights."},{"w":"turn right","vi":"rẽ phải","ex":"{Turn right} and the bank is on your left."},{"w":"go straight","vi":"đi thẳng","ex":"{Go straight} for two blocks."},{"w":"cross the road","vi":"băng qua đường","ex":"Be careful when you {cross the road}."},{"w":"go along the street","vi":"đi dọc theo con đường","ex":"{Go along the street} until you see the park."},{"w":"take the first turning on the right","vi":"rẽ vào ngã rẽ thứ nhất bên phải","ex":"{Take the first turning on the right}, and the café is there."},{"w":"take the second turning on the left","vi":"rẽ vào ngã rẽ thứ hai bên trái","ex":"{Take the second turning on the left} to get to the temple."},{"w":"It's on your right","vi":"Nó ở bên phải của bạn","ex":"Walk for two minutes. {It's on your right}."}]},{"type":"v","title":"Places in a neighbourhood – Các địa điểm thường gặp","words":[{"w":"square","vi":"quảng trường","ex":"There is a fountain in the middle of the {square}."},{"w":"art gallery","vi":"phòng trưng bày mỹ thuật","ex":"We saw many beautiful paintings at the {art gallery}."},{"w":"cathedral","vi":"nhà thờ lớn, thánh đường","ex":"The {cathedral} in the city centre is very old."},{"w":"temple","vi":"ngôi đền, miếu","ex":"Many people visit the {temple} at Tet."},{"w":"railway station","vi":"ga tàu hỏa","ex":"We took a taxi to the {railway station}."},{"w":"live in the suburbs","vi":"sống ở vùng ngoại ô","ex":"I {live in the suburbs} of Ho Chi Minh City."},{"w":"heavy traffic","vi":"tắc nghẽn giao thông","ex":"There is {heavy traffic} in the city centre in the morning."}]},{"type":"g","title":"Comparative adjectives","vi":"So sánh hơn của tính từ","notes":["Tính từ ngắn: adj + -er (+ than): I am taller than you. You are shorter than me. Tính từ 2 âm tiết tận cùng -y cũng là tính từ ngắn: easy → easier, noisy → noisier.","Tính từ dài: more + adj (+ than): This house is more beautiful than my house. The red bike is more expensive than the blue one.","Bất quy tắc: good → better, bad → worse, far → farther/further.","Tận cùng -e chỉ thêm -r (nice → nicer); tính từ 2 âm tiết tận cùng -et, -ow, -er, -le, -ly có thể thêm -er (narrower, quieter, cleverer, friendlier, simpler).","Một nguyên âm + một phụ âm cuối → gấp đôi phụ âm: big → bigger, hot → hotter, fat → fatter, thin → thinner. Không gấp đôi w, x, y: new → newer, slow → slower."],"items":[{"t":"gap","q":"I am ___ than you. (tall)","a":["taller"]},{"t":"gap","q":"You are ___ than me. (short)","a":["shorter"]},{"t":"gap","q":"This exercise is ___ than that one. (easy)","a":["easier"]},{"t":"gap","q":"This house is ___ than my house. (beautiful)","a":["more beautiful"]},{"t":"gap","q":"The red bike is ___ than the blue one. (expensive)","a":["more expensive"]},{"t":"gap","q":"This film is ___ than that one. (good)","a":["better"]},{"t":"gap","q":"The weather today is ___ than yesterday. (bad)","a":["worse"]},{"t":"gap","q":"My school is ___ than yours. (far)","a":["farther","further"]},{"t":"gap","q":"An elephant is ___ than a horse. (big)","a":["bigger"]},{"t":"gap","q":"Summer is ___ than winter. (hot)","a":["hotter"]},{"t":"mc","q":"My new phone is ___ than my old one.","o":["newer","newwer","more new","newest"],"a":["newer"]},{"t":"mc","q":"The countryside is ___ than the city.","o":["quieter","more quiet","quietter","quietest"],"a":["quieter"]},{"t":"mc","q":"This box is ___ than that one.","o":["nicer","nicerer","more nice","nicest"],"a":["nicer"]},{"t":"mc","q":"Mai is ___ than her sister.","o":["more confident","confidenter","most confident","confident"],"a":["more confident"]},{"t":"mc","q":"A car is ___ than a bike.","o":["faster","more fast","fastter","fastest"],"a":["faster"]},{"t":"mc","q":"Which is correct?","o":["thinner","thiner","more thin","thinest"],"a":["thinner"]}]}]},{"g":6,"u":5,"title":"Natural Wonders of Viet Nam","vi":"Kỳ quan thiên nhiên Việt Nam","lessons":[{"type":"v","title":"Places – Địa điểm","words":[{"w":"forest","vi":"khu rừng","ex":"There are many wild animals in the {forest}."},{"w":"island","vi":"hòn đảo","ex":"Phu Quoc is a beautiful {island}."},{"w":"scenery","vi":"phong cảnh","ex":"The {scenery} in Sa Pa is wonderful."},{"w":"landscape","vi":"phong cảnh","ex":"Ha Giang has a beautiful mountain {landscape}."},{"w":"beach","vi":"bãi biển","ex":"We played volleyball on the {beach}."},{"w":"waterfall","vi":"thác nước","ex":"Ban Gioc is a famous {waterfall} in Cao Bang."},{"w":"river","vi":"dòng sông","ex":"The Red {river} flows through Ha Noi."},{"w":"desert","vi":"sa mạc","ex":"It is very hot and dry in the {desert}."},{"w":"mountain","vi":"ngọn núi","ex":"Fansipan is the highest {mountain} in Viet Nam."},{"w":"cave","vi":"hang động","ex":"Son Doong is the biggest {cave} in the world."},{"w":"Ha Long Bay","vi":"Vịnh Hạ Long","ex":"{Ha Long Bay} has thousands of islands."},{"w":"amazing","vi":"tuyệt vời, kinh ngạc","ex":"The view from the top is {amazing}."},{"w":"wonderful","vi":"tuyệt vời","ex":"We had a {wonderful} time in Hoi An."}]},{"type":"v","title":"Travel items & verbs – Đồ dùng khi du lịch và động từ","words":[{"w":"plaster","vi":"băng y tế (băng cá nhân)","ex":"Put a {plaster} on your finger."},{"w":"hurt","vi":"bị đau, bị thương","ex":"Be careful or you will {hurt} yourself."},{"w":"scissors","vi":"cái kéo","ex":"You need {scissors} to cut the paper."},{"w":"sleeping bag","vi":"túi ngủ","ex":"Bring a {sleeping bag} when you go camping."},{"w":"bring","vi":"mang theo","ex":"Don't forget to {bring} your passport."},{"w":"backpack","vi":"ba lô","ex":"I carry my water in a {backpack}."},{"w":"luggage","vi":"hành lý","ex":"We have a lot of {luggage} for the trip."},{"w":"useful","vi":"hữu ích","ex":"A torch is very {useful} at night."},{"w":"compass","vi":"cái la bàn","ex":"Use a {compass} so you don't get lost."},{"w":"get lost","vi":"bị lạc đường","ex":"Take a map or you will {get lost}."},{"w":"overnight","vi":"qua đêm","ex":"We stayed {overnight} in the cave."},{"w":"suncream","vi":"kem chống nắng","ex":"Put on some {suncream} at the beach."},{"w":"pack","vi":"đóng gói, xếp vào túi","ex":"Please {pack} your bag tonight."}]},{"type":"v","title":"Activities and other words – Hoạt động và từ khác","words":[{"w":"leave home","vi":"rời khỏi nhà","ex":"We {leave home} at 6 a.m. for the trip."},{"w":"go for a picnic","vi":"đi dã ngoại","ex":"Let's {go for a picnic} by the lake."},{"w":"make lots of noise","vi":"làm ồn","ex":"Don't {make lots of noise} in the cave."},{"w":"tell the truth","vi":"nói sự thật","ex":"You must always {tell the truth}."},{"w":"visit","vi":"tham quan, đến thăm","ex":"We will {visit} Ha Long Bay next summer."},{"w":"practise","vi":"luyện tập","ex":"I {practise} English every day."},{"w":"natural wonder","vi":"kỳ quan thiên nhiên","ex":"Ha Long Bay is a {natural wonder} of the world."},{"w":"man-made wonder","vi":"kỳ quan nhân tạo","ex":"The Great Wall is a {man-made wonder}."},{"w":"pick flowers","vi":"hái hoa","ex":"Please don't {pick flowers} in the park."}]},{"type":"g","title":"Uncountable nouns","vi":"Danh từ không đếm được","notes":["Chất lỏng, khí: water, milk, tea, oil, coffee, juice, paint, CO2, O2.","Gia vị: sugar, salt, pepper, fish sauce. Chất đặc, sệt: cheese, butter, flour, suncream, ice cream, bread.","Các loại thịt: meat, pork, beef, chicken, fish. Thứ quá nhiều không đếm được: soil, sand, sunlight, rain, snow, hair, time.","Từ khác: furniture, homework, housework, information, ash, wood, luggage, paper, noise.","Danh từ không đếm được không có dạng số nhiều và không đi với a/an: some water, a lot of information."],"items":[{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["water","apple","book","chair"],"a":["water"]},{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["furniture","table","lamp","bed"],"a":["furniture"]},{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["information","question","answer","idea"],"a":["information"]},{"t":"mc","q":"Which noun is COUNTABLE?","o":["egg","bread","rice","sugar"],"a":["egg"]},{"t":"mc","q":"Which is correct?","o":["some luggage","a luggage","two luggages","luggages"],"a":["some luggage"]},{"t":"mc","q":"I have a lot of ___ today.","o":["homework","homeworks","a homework","homeworkes"],"a":["homework"]},{"t":"mc","q":"Can you give me some ___?","o":["information","informations","an information","a information"],"a":["information"]},{"t":"mc","q":"We need some ___ to make a cake.","o":["flour","flours","a flour","an flour"],"a":["flour"]}]},{"type":"g","title":"Quantifiers & must / mustn't","vi":"Từ định lượng và must","notes":["some: câu khẳng định và lời mời (Would you like some tea?), dùng với cả 2 loại danh từ. any: câu phủ định và câu hỏi (I don't have any dogs. Do you have any milk?).","many / a few + danh từ đếm được số nhiều (many books, a few friends); much / a little + danh từ không đếm được (much money, a little milk).","must + V: phải làm (điều rất quan trọng): You must do your homework. mustn't + V: cấm làm: You mustn't run in the library."],"items":[{"t":"gap","q":"I have ___ cookies. (một vài, câu khẳng định)","a":["some"]},{"t":"gap","q":"Would you like ___ tea?","a":["some"]},{"t":"gap","q":"I don't have ___ dogs.","a":["any"]},{"t":"gap","q":"Do you have ___ milk?","a":["any"]},{"t":"gap","q":"There are ___ books on my desk. (nhiều)","a":["many"]},{"t":"gap","q":"I don't have ___ money. (nhiều)","a":["much"]},{"t":"gap","q":"I have ___ friends. (một vài)","a":["a few"]},{"t":"gap","q":"There is ___ milk in the fridge. (một ít)","a":["a little"]},{"t":"gap","q":"You ___ wear a helmet when riding a motorbike. (phải)","a":["must"]},{"t":"gap","q":"You ___ run in the library. (cấm)","a":["mustn't","must not"]},{"t":"mc","q":"How ___ water do you drink every day?","o":["much","many","a few","any"],"a":["much"]},{"t":"mc","q":"You ___ touch the pictures in the museum.","o":["mustn't","must","have","don't"],"a":["mustn't"]},{"t":"mc","q":"There aren't ___ students in the classroom.","o":["any","some","much","a little"],"a":["any"]},{"t":"mc","q":"She has ___ good friends at school.","o":["a few","a little","much","any"],"a":["a few"]},{"t":"mc","q":"You ___ do your homework before class.","o":["must","mustn't","aren't","don't"],"a":["must"]}]}]},{"g":6,"u":6,"title":"Our Tet Holiday","vi":"Tết của chúng ta","lessons":[{"type":"v","title":"Activities at Tet – Hoạt động ngày Tết (1/2)","words":[{"w":"celebrate Tet","vi":"tổ chức mừng Tết","ex":"Vietnamese people {celebrate Tet} in January or February."},{"w":"put lucky money into red envelopes","vi":"bỏ tiền lì xì vào phong bao đỏ","ex":"My parents {put lucky money into red envelopes}."},{"w":"give lucky money","vi":"tặng tiền lì xì","ex":"Grandparents {give lucky money} to children."},{"w":"get lucky money","vi":"nhận tiền lì xì","ex":"Children love to {get lucky money} at Tet."},{"w":"buy peach flowers","vi":"mua hoa đào","ex":"We {buy peach flowers} to decorate the house."},{"w":"make banh chung and banh tet","vi":"làm bánh chưng và bánh tét","ex":"My family {make banh chung and banh tet} before Tet."},{"w":"hold a family gathering","vi":"tổ chức họp mặt gia đình","ex":"We {hold a family gathering} on the first day of Tet."},{"w":"make a wish","vi":"ước nguyện","ex":"Close your eyes and {make a wish}."},{"w":"say wishes","vi":"nói lời chúc","ex":"Children {say wishes} to their grandparents."}]},{"type":"v","title":"Activities at Tet – Hoạt động ngày Tết (2/2)","words":[{"w":"visit relatives","vi":"thăm họ hàng","ex":"We {visit relatives} on the second day of Tet."},{"w":"help with housework","vi":"giúp đỡ việc nhà","ex":"I {help with housework} before Tet."},{"w":"clean the furniture","vi":"lau chùi nội thất","ex":"We {clean the furniture} to welcome the New Year."},{"w":"decorate the house","vi":"trang trí nhà cửa","ex":"We {decorate the house} with flowers and lights."},{"w":"do the shopping","vi":"đi mua sắm","ex":"Mum and I {do the shopping} at the market."},{"w":"cook special food","vi":"nấu món ăn đặc biệt","ex":"My grandmother {cooks special food} at Tet."},{"w":"watch fireworks","vi":"xem pháo hoa","ex":"We {watch fireworks} at midnight."},{"w":"visit a pagoda","vi":"viếng chùa","ex":"Many people {visit a pagoda} at the start of the year."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"knock before you enter","vi":"gõ cửa trước khi vào","ex":"You should {knock before you enter} the room."},{"w":"behave well","vi":"cư xử ngoan","ex":"Children should {behave well} at Tet."},{"w":"eat sweets","vi":"ăn bánh kẹo ngọt","ex":"Don't {eat sweets} before dinner."},{"w":"break things","vi":"làm vỡ đồ","ex":"We shouldn't {break things} at Tet."},{"w":"fight","vi":"đánh nhau","ex":"Brothers shouldn't {fight}."},{"w":"take things from a shelf","vi":"lấy đồ từ kệ","ex":"Ask before you {take things from a shelf}."},{"w":"make a lot of noise","vi":"làm ồn ào","ex":"Don't {make a lot of noise} at night."}]},{"type":"g","title":"Should / shouldn't","vi":"Đưa ra lời khuyên","notes":["should / shouldn't + V (nguyên mẫu): dùng để đưa ra lời khuyên.","You should make a wish at Tet. · We should plant more trees. · You should behave well.","You shouldn't eat lots of sweets. · We shouldn't break things at Tet. · Tom and Jack shouldn't fight."],"items":[{"t":"gap","q":"You ___ make a wish at Tet. (nên)","a":["should"]},{"t":"gap","q":"You ___ eat lots of sweets. (không nên)","a":["shouldn't","should not"]},{"t":"gap","q":"We ___ plant more trees. (nên)","a":["should"]},{"t":"gap","q":"Tom and Jack ___ fight. (không nên)","a":["shouldn't","should not"]},{"t":"gap","q":"You should ___ well at Tet. (behave)","a":["behave"]},{"t":"mc","q":"You have a headache. You ___ go to bed early.","o":["should","shouldn't","mustn't","don't"],"a":["should"]},{"t":"mc","q":"Children ___ break things at Tet.","o":["shouldn't","should","do","must"],"a":["shouldn't"]},{"t":"mc","q":"We should ___ our grandparents at Tet.","o":["visit","visits","visiting","to visit"],"a":["visit"]},{"t":"mc","q":"It's cold. You ___ wear a coat.","o":["should","shouldn't","aren't","don't"],"a":["should"]},{"t":"mc","q":"You ___ make a lot of noise at night.","o":["shouldn't","should","are","do"],"a":["shouldn't"]}]}]},{"g":6,"u":7,"title":"Television","vi":"Truyền hình","lessons":[{"type":"v","title":"TV programmes – Các chương trình truyền hình (1/2)","words":[{"w":"popular channel","vi":"kênh phổ biến, nổi tiếng","ex":"VTV3 is a {popular channel} in Viet Nam."},{"w":"talent show","vi":"chương trình tài năng","ex":"My sister sang in a {talent show}."},{"w":"science programme","vi":"chương trình khoa học","ex":"I learn a lot from this {science programme}."},{"w":"game show","vi":"chương trình trò chơi","ex":"My dad likes watching {game show}s on Saturday."},{"w":"TV programme","vi":"chương trình truyền hình","ex":"What's your favourite {TV programme}?"},{"w":"animated film","vi":"phim hoạt hình","ex":"Frozen is a famous {animated film}."},{"w":"cartoon","vi":"phim hoạt hình","ex":"Doraemon is my favourite {cartoon}."},{"w":"comedy","vi":"hài kịch","ex":"We laughed a lot at the {comedy}."},{"w":"educational programme","vi":"chương trình giáo dục","ex":"This {educational programme} teaches children English."}]},{"type":"v","title":"TV programmes – Các chương trình truyền hình (2/2)","words":[{"w":"sports programme","vi":"chương trình thể thao","ex":"My brother never misses the {sports programme}."},{"w":"animal programme","vi":"chương trình về động vật","ex":"I watch an {animal programme} about elephants."},{"w":"TV series","vi":"phim truyền hình nhiều tập","ex":"This {TV series} has 40 episodes."},{"w":"boring","vi":"chán","ex":"The film was so {boring} that I fell asleep."},{"w":"interesting","vi":"thú vị","ex":"The science programme is very {interesting}."},{"w":"cute character","vi":"nhân vật đáng yêu","ex":"Pikachu is a {cute character}."},{"w":"live","vi":"trực tiếp","ex":"The football match is shown {live} on TV."},{"w":"attract","vi":"thu hút","ex":"Cartoons {attract} a lot of children."}]},{"type":"g","title":"Wh-questions & Conjunctions","vi":"Từ để hỏi và liên từ","notes":["What (cái gì): What do you watch? · Where (ở đâu): Where do you play football? · When (khi nào): When do you play football?","Why (vì sao) → Because …: Why do you like Doraemon? · Who (ai): Who do you like best in Doraemon?","How many (bao nhiêu – đếm được): How many cartoons do you watch every week? · How often (mấy lần): How often do you watch TV?","but (nhưng – đối lập): I like cartoons, but my brother likes game shows. · so (vì vậy – kết quả): I like sport, so I play football twice a week. · and (và – bổ sung): I enjoy animal programmes, and my sister likes them, too."],"items":[{"t":"mc","q":"___ do you watch TV? – In the evening.","o":["When","Where","Who","What"],"a":["When"]},{"t":"mc","q":"___ do you play football? – In the park.","o":["Where","When","Why","How many"],"a":["Where"]},{"t":"mc","q":"___ do you like Doraemon? – Because he is funny.","o":["Why","What","Who","Where"],"a":["Why"]},{"t":"mc","q":"___ do you like best in Doraemon? – Nobita.","o":["Who","What","When","How often"],"a":["Who"]},{"t":"mc","q":"___ cartoons do you watch every week? – Three.","o":["How many","How often","How much","What"],"a":["How many"]},{"t":"mc","q":"___ do you watch TV? – Twice a week.","o":["How often","How many","When","What"],"a":["How often"]},{"t":"mc","q":"___ is your favourite TV programme?","o":["What","Who","Where","Why"],"a":["What"]},{"t":"mc","q":"I like cartoons, ___ my brother likes game shows.","o":["but","so","and","because"],"a":["but"]},{"t":"mc","q":"It was raining, ___ we stayed at home.","o":["so","but","and","or"],"a":["so"]},{"t":"mc","q":"I enjoy animal programmes, ___ my sister likes them, too.","o":["and","but","so","because"],"a":["and"]},{"t":"gap","q":"___ do you live? – I live in Ha Noi.","a":["Where"]},{"t":"gap","q":"___ often do you go swimming? – Once a week.","a":["How"]},{"t":"gap","q":"The film is long, ___ it is very interesting. (nhưng)","a":["but"]},{"t":"gap","q":"I was tired, ___ I went to bed early. (vì vậy)","a":["so"]}]}]},{"g":6,"u":8,"title":"Sports and Games","vi":"Thể thao và trò chơi","lessons":[{"type":"v","title":"Sports – Các môn thể thao","words":[{"w":"do exercise","vi":"tập thể dục","ex":"I {do exercise} every morning."},{"w":"do karate","vi":"tập karate","ex":"My brother {does karate} twice a week."},{"w":"do aerobics","vi":"tập aerobic","ex":"My mum {does aerobics} at the gym."},{"w":"do yoga","vi":"tập yoga","ex":"She {does yoga} to relax."},{"w":"play board games","vi":"chơi trò chơi bàn cờ","ex":"We {play board games} on rainy days."},{"w":"play chess","vi":"chơi cờ vua","ex":"My grandpa likes to {play chess}."},{"w":"play table tennis","vi":"chơi bóng bàn","ex":"We {play table tennis} after school."},{"w":"play volleyball","vi":"chơi bóng chuyền","ex":"The girls {play volleyball} on the beach."},{"w":"play badminton","vi":"chơi cầu lông","ex":"I {play badminton} with my dad."},{"w":"go swimming","vi":"đi bơi","ex":"We {go swimming} in summer."},{"w":"go fishing","vi":"đi câu cá","ex":"My uncle often {goes fishing} at the weekend."},{"w":"go boating","vi":"đi chèo thuyền","ex":"They {go boating} on the lake."},{"w":"go cycling","vi":"đi xe đạp","ex":"Let's {go cycling} in the park."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"win a competition","vi":"thắng một cuộc thi","ex":"Our team {won a competition} last year."},{"w":"become a champion","vi":"trở thành nhà vô địch","ex":"He wants to {become a champion}."},{"w":"send congratulations","vi":"gửi lời chúc mừng","ex":"We {sent congratulations} to the winner."},{"w":"sporty","vi":"khỏe khoắn, thích thể thao","ex":"My brother is very {sporty}."},{"w":"take place","vi":"diễn ra","ex":"The match will {take place} on Sunday."},{"w":"park","vi":"đỗ xe","ex":"You can't {park} here."},{"w":"tidy up","vi":"dọn dẹp","ex":"{Tidy up} your room, please."},{"w":"use the lift","vi":"sử dụng thang máy","ex":"Don't {use the lift} when there is a fire."},{"w":"equipment","vi":"thiết bị, dụng cụ","ex":"The gym has modern {equipment}."},{"w":"run a marathon","vi":"chạy một cuộc đua marathon","ex":"My dad wants to {run a marathon}."},{"w":"goggles","vi":"kính bơi","ex":"Wear {goggles} when you go swimming."},{"w":"racket","vi":"cái vợt","ex":"I need a new tennis {racket}."}]},{"type":"g","title":"Imperatives","vi":"Câu mệnh lệnh","notes":["Khẳng định: V (nguyên mẫu) …: Open the door, please! Tidy up your room.","Phủ định: Don't + V …: Don't talk in class! Don't use the lift when there is a fire.","do + môn chơi 1 người (do exercise, do karate, do yoga); play + môn có ≥ 2 người (play chess, play volleyball); go + V-ing (go swimming, go fishing, go cycling)."],"items":[{"t":"gap","q":"___ the door, please! (mở)","a":["Open"]},{"t":"gap","q":"___ talk in class! (không được)","a":["Don't","Do not"]},{"t":"gap","q":"___ up your room. (dọn)","a":["Tidy"]},{"t":"gap","q":"___ use the lift when there is a fire.","a":["Don't","Do not"]},{"t":"gap","q":"My father often goes ___ at the weekend. (fish)","a":["fishing"]},{"t":"gap","q":"Let's ___ volleyball on the beach.","a":["play"]},{"t":"gap","q":"She ___ yoga every morning.","a":["does"]},{"t":"mc","q":"___ quiet, please!","o":["Be","Are","Is","Being"],"a":["Be"]},{"t":"mc","q":"___ run in the classroom!","o":["Don't","Not","No","Doesn't"],"a":["Don't"]},{"t":"mc","q":"I ___ karate twice a week.","o":["do","play","go","make"],"a":["do"]},{"t":"mc","q":"We ___ badminton after school.","o":["play","do","go","make"],"a":["play"]},{"t":"mc","q":"They ___ cycling in the park.","o":["go","play","do","make"],"a":["go"]},{"t":"mc","q":"___ your hands before meals.","o":["Wash","Washing","Washes","To wash"],"a":["Wash"]}]},{"type":"g","title":"Past simple","vi":"Thì quá khứ đơn","notes":["Dùng diễn tả hành động đã xảy ra và kết thúc trong quá khứ: I watched TV last night. He went to school yesterday.","(+) S + V2/V-ed · (–) S + didn't + V · (?) Did + S + V …?","Dấu hiệu: yesterday, ago, last (night/week/year), in the past, in + năm quá khứ (in 2025).","Phát âm -ed: /t/ sau s, sh, ch, k, p, f (cooked, stopped, watched); /ɪd/ sau t, d (wanted, visited, needed); /d/ sau các âm còn lại (played, opened, studied)."],"items":[{"t":"gap","q":"I ___ football yesterday. (play)","a":["played"]},{"t":"gap","q":"They ___ their homework last night. (do)","a":["did"]},{"t":"gap","q":"We ___ any new books last Sunday. (not buy)","a":["didn't buy","did not buy"]},{"t":"gap","q":"___ you visit the museum in 2025?","a":["Did"]},{"t":"gap","q":"He ___ to school by bike yesterday. (go)","a":["went"]},{"t":"gap","q":"She ___ a letter to her friend last week. (write)","a":["wrote"]},{"t":"gap","q":"I ___ my grandparents two days ago. (visit)","a":["visited"]},{"t":"gap","q":"We ___ a lot of photos on our trip. (take)","a":["took"]},{"t":"mc","q":"I ___ a new bike last month.","o":["bought","buyed","buy","buys"],"a":["bought"]},{"t":"mc","q":"___ she watch TV last night?","o":["Did","Does","Do","Was"],"a":["Did"]},{"t":"mc","q":"They didn't ___ to the party.","o":["come","came","comes","coming"],"a":["come"]},{"t":"mc","q":"Which word has -ed pronounced /ɪd/?","o":["wanted","played","cooked","opened"],"a":["wanted"]},{"t":"mc","q":"Which word has -ed pronounced /t/?","o":["watched","visited","needed","studied"],"a":["watched"]},{"t":"mc","q":"We met our teacher ___.","o":["yesterday","tomorrow","now","every day"],"a":["yesterday"]}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (1/3)","words":[{"w":"went","vi":"đi (quá khứ của go)","ex":"We {went} to the zoo last Sunday."},{"w":"grew","vi":"trồng, lớn lên (quá khứ của grow)","ex":"My grandma {grew} vegetables in her garden."},{"w":"gave","vi":"đưa cho, tặng (quá khứ của give)","ex":"She {gave} me a nice present."},{"w":"did","vi":"làm (quá khứ của do)","ex":"I {did} my homework last night."},{"w":"had","vi":"có (quá khứ của have)","ex":"We {had} a great time at the beach."},{"w":"ate","vi":"ăn (quá khứ của eat)","ex":"He {ate} two bowls of pho."},{"w":"taught","vi":"dạy (quá khứ của teach)","ex":"Mr Nam {taught} us maths last year."},{"w":"took","vi":"lấy, mang đi (quá khứ của take)","ex":"She {took} a lot of photos."},{"w":"told","vi":"kể, nói (quá khứ của tell)","ex":"Grandpa {told} us a funny story."},{"w":"began","vi":"bắt đầu (quá khứ của begin)","ex":"The film {began} at 8 p.m."},{"w":"became","vi":"trở thành (quá khứ của become)","ex":"He {became} a champion in 2024."}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (2/3)","words":[{"w":"bought","vi":"mua (quá khứ của buy)","ex":"I {bought} a new bag yesterday."},{"w":"beat","vi":"đánh bại (quá khứ của beat)","ex":"Our team {beat} their team 3–1."},{"w":"cut","vi":"cắt (quá khứ của cut)","ex":"Mum {cut} the cake into eight pieces."},{"w":"drank","vi":"uống (quá khứ của drink)","ex":"I {drank} a glass of milk."},{"w":"put","vi":"đặt, để (quá khứ của put)","ex":"He {put} the book on the table."},{"w":"won","vi":"chiến thắng (quá khứ của win)","ex":"Viet Nam {won} the match."},{"w":"knew","vi":"biết (quá khứ của know)","ex":"I {knew} the answer."},{"w":"read","vi":"đọc (quá khứ của read)","ex":"I {read} a good book last week."},{"w":"saw","vi":"nhìn thấy (quá khứ của see)","ex":"We {saw} a big elephant at the zoo."},{"w":"sent","vi":"gửi đi (quá khứ của send)","ex":"She {sent} me an email."},{"w":"sold","vi":"bán (quá khứ của sell)","ex":"They {sold} their old car."}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (3/3)","words":[{"w":"swam","vi":"bơi (quá khứ của swim)","ex":"We {swam} in the sea."},{"w":"spoke","vi":"nói (quá khứ của speak)","ex":"He {spoke} English very well."},{"w":"made","vi":"làm, tạo ra (quá khứ của make)","ex":"Mum {made} a cake for me."},{"w":"wrote","vi":"viết (quá khứ của write)","ex":"I {wrote} a postcard to my friend."},{"w":"wore","vi":"mặc, đội (quá khứ của wear)","ex":"She {wore} a red dress to the party."},{"w":"rode","vi":"đạp xe, cưỡi (quá khứ của ride)","ex":"He {rode} his bike to school."},{"w":"held","vi":"cầm, nắm, tổ chức (quá khứ của hold)","ex":"They {held} a party last night."},{"w":"heard","vi":"nghe (quá khứ của hear)","ex":"I {heard} a strange noise."},{"w":"met","vi":"gặp gỡ (quá khứ của meet)","ex":"I {met} my best friend at the park."}]}]},{"g":6,"u":9,"title":"Cities of the World","vi":"Các thành phố trên thế giới","lessons":[{"type":"v","title":"Places – Địa điểm","words":[{"w":"famous landmark","vi":"địa danh nổi tiếng","ex":"The Eiffel Tower is a {famous landmark}."},{"w":"Eiffel Tower","vi":"tháp Eiffel (Paris, Pháp)","ex":"We took photos in front of the {Eiffel Tower}."},{"w":"Sydney Opera House","vi":"nhà hát Opera Sydney (Úc)","ex":"The {Sydney Opera House} looks like big shells."},{"w":"Big Ben","vi":"tháp đồng hồ Big Ben (London, Anh)","ex":"{Big Ben} is a famous clock tower in London."},{"w":"Merlion","vi":"tượng sư tử biển (Singapore)","ex":"The {Merlion} is a symbol of Singapore."},{"w":"building","vi":"tòa nhà","ex":"It is the tallest {building} in the city."},{"w":"stall","vi":"gian hàng","ex":"She sells fruit at a small {stall}."},{"w":"street food","vi":"món ăn đường phố","ex":"Ha Noi is famous for its {street food}."},{"w":"night market","vi":"chợ đêm","ex":"We bought souvenirs at the {night market}."},{"w":"river bank","vi":"bờ sông","ex":"We walked along the {river bank}."},{"w":"floating market","vi":"chợ nổi","ex":"Cai Rang is a famous {floating market}."},{"w":"royal palace","vi":"cung điện hoàng gia","ex":"The king lived in the {royal palace}."}]},{"type":"v","title":"Adjectives and other words – Tính từ và từ khác","words":[{"w":"exciting","vi":"thú vị","ex":"Bangkok is an {exciting} city."},{"w":"famous","vi":"nổi tiếng","ex":"Paris is {famous} for the Eiffel Tower."},{"w":"old","vi":"cũ, cổ","ex":"Hoi An is a very {old} town."},{"w":"quiet","vi":"yên tĩnh","ex":"The village is {quiet} at night."},{"w":"crowded","vi":"đông đúc","ex":"The market is always {crowded} at weekends."},{"w":"rainy","vi":"có mưa, mưa nhiều","ex":"London is often {rainy}."},{"w":"sunny","vi":"có nắng","ex":"It's {sunny} today, so let's go to the beach."},{"w":"friendly","vi":"thân thiện","ex":"The people in Hue are very {friendly}."},{"w":"helpful","vi":"sẵn sàng giúp đỡ","ex":"The tour guide was very {helpful}."},{"w":"cute","vi":"đáng yêu","ex":"What a {cute} little dog!"},{"w":"map","vi":"bản đồ","ex":"Look at the {map} to find the way."},{"w":"postcard","vi":"bưu thiếp","ex":"I sent my friend a {postcard} from Paris."},{"w":"shell","vi":"vỏ sò","ex":"We collected {shell}s on the beach."},{"w":"rent","vi":"thuê, mướn","ex":"We {rent} bikes to go around the city."}]},{"type":"g","title":"Possessive adjectives & pronouns","vi":"Tính từ sở hữu & đại từ sở hữu","notes":["Tính từ sở hữu (my, your, his, her, its, our, their) đứng trước danh từ: This is my book. Her father is a doctor.","Đại từ sở hữu (mine, yours, his, hers, its, ours, theirs) đứng một mình, không có danh từ theo sau: This book is mine. That bike is hers.","Your pen is blue. His is red. (His = his pen)"],"items":[{"t":"gap","q":"This is ___ book. (của tôi – tính từ sở hữu)","a":["my"]},{"t":"gap","q":"This book is ___. (của tôi – đại từ sở hữu)","a":["mine"]},{"t":"gap","q":"That bike is ___. (của cô ấy)","a":["hers"]},{"t":"gap","q":"___ father is a doctor. (của cô ấy)","a":["Her"]},{"t":"gap","q":"Your pen is blue. ___ is red. (của anh ấy)","a":["His"]},{"t":"gap","q":"This is our house. It's ___.","a":["ours"]},{"t":"gap","q":"These are their toys. They're ___.","a":["theirs"]},{"t":"mc","q":"Is this pencil ___? – Yes, it's mine.","o":["yours","your","you","you're"],"a":["yours"]},{"t":"mc","q":"The dog is wagging ___ tail.","o":["its","it's","it","his"],"a":["its"]},{"t":"mc","q":"That isn't my bag. Mine is black. – Is it ___?","o":["hers","her","she","she's"],"a":["hers"]},{"t":"mc","q":"We love ___ city very much.","o":["our","ours","we","us"],"a":["our"]},{"t":"mc","q":"Their house is big, but ___ is small.","o":["ours","our","we","us"],"a":["ours"]}]}]},{"g":6,"u":10,"title":"Our Houses in the Future","vi":"Ngôi nhà của chúng ta trong tương lai","lessons":[{"type":"v","title":"House appliances – Thiết bị trong nhà","words":[{"w":"electric cooker","vi":"nồi cơm điện","ex":"We cook rice in an {electric cooker}."},{"w":"cook rice","vi":"nấu cơm","ex":"My mum {cooks rice} for dinner."},{"w":"electric fan","vi":"quạt điện","ex":"Turn on the {electric fan}. It's hot."},{"w":"washing machine","vi":"máy giặt","ex":"The {washing machine} can wash and dry clothes."},{"w":"wash and dry clothes","vi":"giặt và sấy khô quần áo","ex":"Robots will {wash and dry clothes} for us."},{"w":"dishwasher","vi":"máy rửa chén","ex":"The {dishwasher} washes and dries the dishes."},{"w":"fridge","vi":"tủ lạnh","ex":"The {fridge} keeps food fresh."},{"w":"keep food fresh","vi":"giữ thức ăn tươi","ex":"A fridge helps {keep food fresh}."},{"w":"smart clock","vi":"đồng hồ thông minh","ex":"My {smart clock} wakes me up at 6 a.m."},{"w":"wireless TV","vi":"TV không dây","ex":"With a {wireless TV}, we can send and receive emails."},{"w":"receive and send emails","vi":"nhận và gửi email","ex":"I can {receive and send emails} on my phone."},{"w":"laptop","vi":"máy tính xách tay","ex":"I do my homework on my {laptop}."}]},{"type":"v","title":"Daily routines – Công việc hằng ngày","words":[{"w":"clean the floor","vi":"lau sàn nhà","ex":"A robot will {clean the floor}."},{"w":"cook meals","vi":"nấu ăn","ex":"My dad {cooks meals} at weekends."},{"w":"feed the dogs and cats","vi":"cho chó mèo ăn","ex":"I {feed the dogs and cats} every morning."},{"w":"buy food from the supermarket","vi":"mua thức ăn ở siêu thị","ex":"We {buy food from the supermarket} on Sundays."},{"w":"water the flowers","vi":"tưới hoa","ex":"Don't forget to {water the flowers}."},{"w":"contact my friends","vi":"liên lạc bạn bè","ex":"I {contact my friends} by phone."},{"w":"look after the house","vi":"trông coi nhà cửa","ex":"A robot will {look after the house} when we are away."},{"w":"take care of children","vi":"chăm sóc trẻ em","ex":"Grandma helps {take care of children}."},{"w":"iron the clothes","vi":"ủi quần áo","ex":"Mum {irons the clothes} on Sunday."},{"w":"do the housework","vi":"làm việc nhà","ex":"Robots will {do the housework} in the future."}]},{"type":"v","title":"Places – Cụm từ chỉ vị trí","words":[{"w":"in the ocean","vi":"ở trong đại dương","ex":"My future house will be {in the ocean}."},{"w":"by the sea","vi":"ở gần biển","ex":"They live in a villa {by the sea}."},{"w":"in the city","vi":"ở trong thành phố","ex":"It's noisy {in the city}."},{"w":"in the countryside","vi":"ở vùng nông thôn","ex":"The air is fresh {in the countryside}."},{"w":"in the town","vi":"ở trong thị trấn","ex":"There is a small market {in the town}."},{"w":"in the mountains","vi":"ở trong núi","ex":"We stayed in a hut {in the mountains}."},{"w":"in the sky","vi":"ở trên bầu trời","ex":"Birds fly {in the sky}."},{"w":"on the Moon","vi":"ở trên mặt trăng","ex":"People might live {on the Moon} one day."}]},{"type":"g","title":"Future simple & might","vi":"Tương lai đơn và might","notes":["Will: (+) S + will + V · (–) S + will not (won't) + V · (?) Will + S + V? — I will do my homework tonight. She won't go to class tomorrow.","Dấu hiệu: tomorrow, next (week/year), in the future, in + năm tương lai (in 2050), one day / someday.","Might (có thể – không chắc chắn): (+) S + might + V · (–) S + might not + V · (?) Might + S + V? — I might watch a movie later. He might not visit you tomorrow."],"items":[{"t":"gap","q":"I ___ my homework tonight. (do)","a":["will do","'ll do"]},{"t":"gap","q":"She ___ to class tomorrow. (not go)","a":["won't go","will not go"]},{"t":"gap","q":"___ she travel to Da Lat tomorrow?","a":["Will"]},{"t":"gap","q":"I ___ a movie later. (watch – có thể, không chắc chắn)","a":["might watch"]},{"t":"gap","q":"He ___ you tomorrow. (not visit – có thể)","a":["might not visit"]},{"t":"gap","q":"In 2050, people ___ on the Moon. (live)","a":["will live"]},{"t":"mc","q":"Our house ___ a robot in the future.","o":["will have","has","had","having"],"a":["will have"]},{"t":"mc","q":"It ___ rain tomorrow. I'm not sure.","o":["might","will","must","should"],"a":["might"]},{"t":"mc","q":"___ you come to my party next Sunday?","o":["Will","Do","Did","Are"],"a":["Will"]},{"t":"mc","q":"Robots ___ do the housework in the future.","o":["will","did","were","are doing"],"a":["will"]},{"t":"mc","q":"Which word is a signal for the future simple?","o":["next year","yesterday","now","last week"],"a":["next year"]},{"t":"mc","q":"I ___ go out tonight because I am tired.","o":["won't","don't","didn't","wasn't"],"a":["won't"]}]}]},{"g":6,"u":11,"title":"Our Greener World","vi":"Thế giới xanh hơn của chúng ta","lessons":[{"type":"v","title":"Green activities – Hoạt động xanh","words":[{"w":"greener world","vi":"thế giới xanh hơn","ex":"Let's work together for a {greener world}."},{"w":"go on a picnic","vi":"đi dã ngoại","ex":"We {go on a picnic} in the park every spring."},{"w":"help the environment","vi":"giúp môi trường","ex":"Recycling can {help the environment}."},{"w":"plant trees and flowers","vi":"trồng cây và hoa","ex":"Our class will {plant trees and flowers} in the schoolyard."},{"w":"pick up rubbish","vi":"nhặt rác","ex":"We {pick up rubbish} on the beach."},{"w":"use reusable bags when shopping","vi":"dùng túi tái sử dụng khi mua sắm","ex":"We should {use reusable bags when shopping}."},{"w":"reduce","vi":"giảm bớt","ex":"We should {reduce} the amount of plastic we use."},{"w":"reuse","vi":"tái sử dụng","ex":"You can {reuse} glass bottles."},{"w":"recycle","vi":"tái chế","ex":"We {recycle} paper and plastic."},{"w":"cycle","vi":"đi xe đạp","ex":"I {cycle} to school every day."},{"w":"walk","vi":"đi bộ","ex":"Let's {walk} instead of going by car."}]},{"type":"v","title":"Things and actions – Đồ vật và hành động","words":[{"w":"recycling bin","vi":"thùng tái chế","ex":"Put the cans in the {recycling bin}."},{"w":"plastic bag","vi":"túi nhựa","ex":"Don't use too many {plastic bag}s."},{"w":"plastic bottle","vi":"chai nhựa","ex":"I reuse my {plastic bottle}."},{"w":"glass","vi":"thủy tinh","ex":"These jars are made of {glass}."},{"w":"paper","vi":"giấy","ex":"We recycle old {paper}."},{"w":"clothes","vi":"quần áo","ex":"I give my old {clothes} to charity."},{"w":"noise","vi":"tiếng ồn","ex":"There is too much {noise} in the city."},{"w":"exchange","vi":"trao đổi","ex":"I {exchange} my clothes with my brother."},{"w":"give something to charity","vi":"quyên góp cho hội từ thiện","ex":"I often {give my old clothes to charity}."},{"w":"throw away","vi":"vứt đi","ex":"Don't {throw away} plastic bags."},{"w":"instead of","vi":"thay vì","ex":"I give my old books to poor children {instead of} throwing them away."}]},{"type":"g","title":"First conditional","vi":"Câu điều kiện loại 1","notes":["Diễn tả điều có thể xảy ra trong tương lai: If + S + V (hiện tại đơn), S + will / won't + V.","If it rains, I will stay at home. · If you don't study hard, you won't get good marks. · Lan won't have a new bike if she doesn't study well."],"items":[{"t":"gap","q":"If it ___, I will stay at home. (rain)","a":["rains"]},{"t":"gap","q":"If you don't study hard, you ___ good marks. (not get)","a":["won't get","will not get"]},{"t":"gap","q":"If we hurry, we ___ to catch the bus. (manage)","a":["will manage","'ll manage"]},{"t":"gap","q":"Lan won't have a new bike if she ___ well. (not study)","a":["doesn't study","does not study"]},{"t":"gap","q":"If we recycle more, we ___ the environment. (help)","a":["will help"]},{"t":"mc","q":"If you ___ plastic bottles, you will help the environment.","o":["reuse","reused","will reuse","reusing"],"a":["reuse"]},{"t":"mc","q":"If it is sunny tomorrow, we ___ on a picnic.","o":["will go","go","went","goes"],"a":["will go"]},{"t":"mc","q":"If he ___ up early, he will miss the bus.","o":["doesn't get","won't get","didn't get","not get"],"a":["doesn't get"]},{"t":"mc","q":"We ___ more trees if we have time.","o":["will plant","plant","planted","plants"],"a":["will plant"]}]},{"type":"g","title":"Articles: a / an / the","vi":"Mạo từ","notes":["a / an = \"một\": dùng khi nói về một thứ chưa xác định hoặc nhắc đến lần đầu. a + phụ âm (a book, a dog); an + nguyên âm u, e, o, a, i (an apple, an egg, an orange).","the: dùng cho đối tượng đã xác định, người nói và người nghe đều biết (Close the door.); vật duy nhất (the Sun, the Moon, the Earth); khi nhắc lại lần thứ hai (He sees a cat. The cat is cute.)."],"items":[{"t":"gap","q":"I have ___ new pen.","a":["a"]},{"t":"gap","q":"She has ___ apple.","a":["an"]},{"t":"gap","q":"___ Sun is hot.","a":["The"]},{"t":"gap","q":"He sees a cat. ___ cat is cute.","a":["The"]},{"t":"gap","q":"I eat ___ egg every morning.","a":["an"]},{"t":"mc","q":"Close ___ door, please.","o":["the","a","an","x"],"a":["the"]},{"t":"mc","q":"My mother is ___ teacher.","o":["a","an","the","x"],"a":["a"]},{"t":"mc","q":"I like to see ___ Moon at night.","o":["the","a","an","x"],"a":["the"]},{"t":"mc","q":"There is ___ orange on the table.","o":["an","a","the","x"],"a":["an"]}]}]},{"g":6,"u":12,"title":"Robots","vi":"Rô-bốt","lessons":[{"type":"v","title":"Robots – Các loại rô-bốt","words":[{"w":"home robot","vi":"rô-bốt làm việc nhà","ex":"A {home robot} can clean the house."},{"w":"teacher robot","vi":"rô-bốt giáo viên","ex":"The {teacher robot} can teach English."},{"w":"teach","vi":"dạy","ex":"Robots will {teach} children in the future."},{"w":"worker robot","vi":"rô-bốt công nhân","ex":"A {worker robot} can build houses."},{"w":"build houses","vi":"xây nhà","ex":"Worker robots can {build houses}."},{"w":"move heavy things","vi":"di chuyển đồ vật nặng","ex":"Robots can {move heavy things} easily."},{"w":"doctor robot","vi":"rô-bốt bác sĩ","ex":"A {doctor robot} can look after sick people."},{"w":"look after sick people","vi":"chăm sóc người bệnh","ex":"Doctor robots will {look after sick people}."},{"w":"space robot","vi":"rô-bốt không gian","ex":"A {space robot} can build space stations."},{"w":"build space stations","vi":"xây trạm không gian","ex":"Space robots help {build space stations}."},{"w":"useful","vi":"có ích","ex":"Robots are very {useful}."},{"w":"smart","vi":"thông minh","ex":"My robot is very {smart}."},{"w":"understand our feelings","vi":"hiểu cảm xúc của chúng ta","ex":"Robots can't {understand our feelings}."},{"w":"strong","vi":"mạnh","ex":"Worker robots are very {strong}."}]},{"type":"v","title":"Daily activities – Hoạt động hằng ngày","words":[{"w":"do household chores","vi":"làm công việc nhà","ex":"Robots will {do household chores} for us."},{"w":"cook meals","vi":"nấu các bữa ăn","ex":"Our robot can {cook meals}."},{"w":"do the dishes","vi":"rửa chén bát","ex":"I {do the dishes} after dinner."},{"w":"do the washing","vi":"giặt quần áo","ex":"The robot will {do the washing} on Monday."},{"w":"iron the clothes","vi":"ủi quần áo","ex":"Can your robot {iron the clothes}?"},{"w":"repair a broken machine","vi":"sửa chữa máy móc bị hỏng","ex":"This robot can {repair a broken machine}."},{"w":"put toys away","vi":"cất đồ chơi","ex":"{Put toys away} after you play."},{"w":"clean the house","vi":"lau dọn nhà cửa","ex":"We {clean the house} at the weekend."},{"w":"pick fruit","vi":"hái trái cây","ex":"Robots can {pick fruit} on farms."},{"w":"water plants","vi":"tưới cây","ex":"Please {water plants} in the garden."},{"w":"work as a guard","vi":"làm bảo vệ","ex":"The robot can {work as a guard} at night."},{"w":"be interested in","vi":"thích, quan tâm đến","ex":"I {am interested in} robots."}]},{"type":"g","title":"Superlative adjectives","vi":"So sánh nhất (tính từ ngắn)","notes":["Công thức: the + adj ngắn + -est: He is the tallest in his class. This dog is the smallest of the three dogs.","Tận cùng -e chỉ thêm -st: large → the largest. Một nguyên âm + một phụ âm cuối → gấp đôi phụ âm: big → the biggest.","Bất quy tắc: good → the best, bad → the worst, far → the farthest/furthest, many/much → the most, little → the least."],"items":[{"t":"gap","q":"Mount Everest is the ___ mountain in the world. (high)","a":["highest"]},{"t":"gap","q":"This is the ___ day of the year so far. (cold)","a":["coldest"]},{"t":"gap","q":"This is the ___ building in our city. (big)","a":["biggest"]},{"t":"gap","q":"Tom is the ___ runner in his team. (fast)","a":["fastest"]},{"t":"gap","q":"He is the ___ in his class. (tall)","a":["tallest"]},{"t":"gap","q":"An elephant is the ___ animal here. (large)","a":["largest"]},{"t":"gap","q":"This is the ___ film I have ever seen. (bad)","a":["worst"]},{"t":"mc","q":"This is ___ book in my collection.","o":["the best","the good","the better","best"],"a":["the best"]},{"t":"mc","q":"She is ___ student in my class.","o":["the hardest","the hard","the harder","hardest"],"a":["the hardest"]},{"t":"mc","q":"That is ___ cat of all.","o":["the cutest","the cute","the cuter","cutest"],"a":["the cutest"]},{"t":"mc","q":"He runs ___ than his brother.","o":["faster","fast","the fastest","fastest"],"a":["faster"]},{"t":"mc","q":"This exercise is ___ in the test.","o":["the easiest","the easy","the easier","easiest"],"a":["the easiest"]}]}]},{"g":7,"u":1,"title":"Hobbies","vi":"Sở thích","lessons":[{"type":"v","title":"Common hobbies – Các sở thích phổ biến (1/2)","words":[{"w":"building dollhouses","vi":"xây nhà búp bê","ex":"{Building dollhouses} needs cardboard, glue and creativity."},{"w":"cardboard","vi":"bìa cứng","ex":"You can make a model house from {cardboard}."},{"w":"glue","vi":"keo dán","ex":"Use some {glue} to stick the pieces together."},{"w":"use creativity","vi":"dùng sự sáng tạo","ex":"You need to {use creativity} to build dollhouses."},{"w":"horse riding","vi":"cưỡi ngựa","ex":"My cousin loves {horse riding}."},{"w":"making models","vi":"làm mô hình","ex":"{Making models} is my brother's hobby."},{"w":"collecting coins","vi":"sưu tập đồng xu","ex":"I love {collecting coins} from different countries."},{"w":"collecting teddy bears","vi":"sưu tập gấu bông","ex":"She enjoys {collecting teddy bears}."},{"w":"gardening","vi":"làm vườn","ex":"{Gardening} teaches us valuable lessons."}]},{"type":"v","title":"Common hobbies – Các sở thích phổ biến (2/2)","words":[{"w":"valuable lesson","vi":"bài học quý báu","ex":"Gardening gives children a {valuable lesson} about patience."},{"w":"responsibility","vi":"trách nhiệm","ex":"Taking care of plants teaches you {responsibility}."},{"w":"jogging","vi":"chạy bộ","ex":"My dad goes {jogging} every morning."},{"w":"camping","vi":"cắm trại","ex":"We go {camping} in the mountains every summer."},{"w":"doing judo","vi":"tập võ judo","ex":"Tom likes {doing judo}."},{"w":"playing the guitar","vi":"chơi đàn ghi-ta","ex":"{Playing the guitar} is my favourite hobby."},{"w":"outdoor activity","vi":"hoạt động ngoài trời","ex":"Camping is a fun {outdoor activity}."},{"w":"patient","vi":"kiên nhẫn","ex":"You must be {patient} when you go fishing."},{"w":"maturity","vi":"sự trưởng thành","ex":"Taking care of pets shows {maturity}."}]},{"type":"g","title":"Likes / dislikes + V-ing","vi":"Diễn đạt sở thích","notes":["Thích: I like / love / enjoy + V-ing: I love collecting coins. Cách khác: My hobby is + V-ing: My hobby is playing tennis.","Không thích: I hate / don't like / don't love / don't enjoy + V-ing: I hate riding a horse. I don't like gardening.","go + V-ing (go jogging, go swimming, go camping); do + môn 1 người (do judo, do yoga); play + môn ≥ 2 người (play chess, play football); play + the + nhạc cụ (play the guitar)."],"items":[{"t":"gap","q":"I love ___ coins. (collect)","a":["collecting"]},{"t":"gap","q":"My hobby is ___ tennis. (play)","a":["playing"]},{"t":"gap","q":"She doesn't like ___. (garden)","a":["gardening"]},{"t":"gap","q":"They enjoy ___ models. (make)","a":["making"]},{"t":"gap","q":"My brother plays ___ guitar.","a":["the"]},{"t":"mc","q":"I hate ___ a horse.","o":["riding","ride","to rides","rode"],"a":["riding"]},{"t":"mc","q":"We often go ___ in summer.","o":["camping","camp","to camp","camps"],"a":["camping"]},{"t":"mc","q":"Lan ___ judo twice a week.","o":["does","plays","goes","makes"],"a":["does"]},{"t":"mc","q":"My father enjoys ___ the piano.","o":["playing","play","plays","played"],"a":["playing"]},{"t":"mc","q":"Do you like ___ dollhouses?","o":["building","build","builds","built"],"a":["building"]}]},{"type":"g","title":"Present simple (review)","vi":"Thì hiện tại đơn (ôn tập)","notes":["(+) S + V / V-s / V-es · (–) S + don't / doesn't + V · (?) Do / Does + S + V …?","Dấu hiệu: always, usually, often, sometimes, rarely, hardly, never (đứng trước V thường, sau \"be\"); once a week, twice a week, every day.","Phát âm -s/-es: /s/ sau th, p, k, f, t; /ɪz/ sau x, s, ch, sh, z; /z/ sau các âm còn lại."],"items":[{"t":"gap","q":"My mother ___ in the garden every weekend. (work)","a":["works"]},{"t":"gap","q":"We ___ dollhouses on Sundays. (build)","a":["build"]},{"t":"gap","q":"She ___ horse riding. (not like)","a":["doesn't like","does not like"]},{"t":"gap","q":"___ your brother collect stamps?","a":["Does"]},{"t":"gap","q":"He usually ___ to school at 6.30. (go)","a":["goes"]},{"t":"gap","q":"My friends ___ chess after school. (not play)","a":["don't play","do not play"]},{"t":"mc","q":"Nam ___ his model planes very carefully.","o":["makes","make","making","is make"],"a":["makes"]},{"t":"mc","q":"___ they go camping every summer?","o":["Do","Does","Are","Is"],"a":["Do"]},{"t":"mc","q":"She is ___ late for class.","o":["never","never is","is never","not never"],"a":["never"]},{"t":"mc","q":"Which verb has the ending pronounced /ɪz/?","o":["washes","plays","stops","reads"],"a":["washes"]},{"t":"mc","q":"Which verb has the ending pronounced /z/?","o":["listens","thanks","stops","watches"],"a":["listens"]}]}]},{"g":7,"u":2,"title":"Healthy Living","vi":"Sống khỏe","lessons":[{"type":"v","title":"Healthy activities – Hoạt động lành mạnh","words":[{"w":"outdoor activities","vi":"hoạt động ngoài trời","ex":"{Outdoor activities} are good for your health."},{"w":"good for your health","vi":"tốt cho sức khỏe","ex":"Eating vegetables is {good for your health}."},{"w":"exercise","vi":"tập thể dục","ex":"You should {exercise} every day."},{"w":"improve your health","vi":"cải thiện sức khỏe","ex":"Sleeping well can {improve your health}."},{"w":"brush your teeth","vi":"đánh răng","ex":"{Brush your teeth} twice a day."},{"w":"wash your hands","vi":"rửa tay","ex":"{Wash your hands} before meals."},{"w":"eat tofu","vi":"ăn đậu phụ","ex":"Vegetarians often {eat tofu}."},{"w":"coloured vegetables","vi":"rau củ có màu sắc","ex":"{Coloured vegetables} have lots of vitamins."},{"w":"don't touch your face with dirty hands","vi":"không chạm vào mặt với đôi tay bẩn","ex":"{Don't touch your face with dirty hands}."},{"w":"wear a face mask","vi":"đeo khẩu trang","ex":"{Wear a face mask} when going out."},{"w":"avoid crowds","vi":"tránh đám đông","ex":"You should {avoid crowds} when you are ill."},{"w":"keep your house clean","vi":"giữ nhà cửa sạch sẽ","ex":"{Keep your house clean} to stay healthy."}]},{"type":"v","title":"Health problems – Vấn đề sức khỏe","words":[{"w":"have sunburn","vi":"bị cháy nắng","ex":"I {have sunburn} because I stayed in the sun too long."},{"w":"suncream","vi":"kem chống nắng","ex":"Use {suncream} to avoid sunburn."},{"w":"have chapped lips","vi":"bị nứt nẻ môi","ex":"I {have chapped lips} in winter."},{"w":"lip balm","vi":"son dưỡng môi","ex":"Put on some {lip balm}."},{"w":"have red spots","vi":"bị nổi mẩn đỏ","ex":"My skin {has red spots} after eating seafood."},{"w":"pimples","vi":"mụn","ex":"Teenagers often have {pimples}."},{"w":"acne","vi":"mụn trứng cá","ex":"Don't pop your {acne}."},{"w":"eyes get tired","vi":"mắt bị mỏi","ex":"My {eyes get tired} when I use my phone too long."},{"w":"eyedrops","vi":"thuốc nhỏ mắt","ex":"The doctor gave me some {eyedrops}."},{"w":"dim light","vi":"ánh sáng mờ","ex":"You shouldn't read in {dim light}."},{"w":"put on weight","vi":"tăng cân","ex":"Eating too much fast food makes you {put on weight}."},{"w":"avoid fast food","vi":"tránh thức ăn nhanh","ex":"Try to {avoid fast food} and soft drinks."},{"w":"soft drinks","vi":"nước ngọt","ex":"{Soft drinks} contain a lot of sugar."},{"w":"skin condition","vi":"tình trạng da","ex":"The weather affects your {skin condition}."}]},{"type":"g","title":"Simple sentences","vi":"Câu đơn","notes":["Câu đơn có 1 chủ ngữ và 1 động từ chính (có thể ghép: 2 chủ ngữ cùng 1 động từ hoặc 1 chủ ngữ với 2 động từ): I like going swimming.","Ghép 2 câu thành 1 câu đơn: My brother loves outdoor activities. I love outdoor activities, too. → My brother and I love outdoor activities.","My father plays games in his free time. He also watches TV in his free time. → My father plays games and watches TV in his free time."],"items":[{"t":"mc","q":"We avoid sweetened food. We avoid soft drinks. → ?","o":["We avoid sweetened food and soft drinks.","We avoid sweetened food we avoid soft drinks.","We and soft drinks avoid sweetened food.","We avoid sweetened food, and soft drinks too we avoid."],"a":["We avoid sweetened food and soft drinks."]},{"t":"mc","q":"My dad loves watching football. I love watching football, too. → ?","o":["My dad and I love watching football.","My dad loves and I watching football.","My dad love watching football and I.","I and my dad loves watching football."],"a":["My dad and I love watching football."]},{"t":"mc","q":"You should wear a hat. You should wear suncream. → ?","o":["You should wear a hat and suncream.","You should wear a hat should wear suncream.","You and suncream should wear a hat.","You wear a hat should and suncream."],"a":["You should wear a hat and suncream."]},{"t":"mc","q":"My mother read the health tips. My mother downloaded the health tips. → ?","o":["My mother read and downloaded the health tips.","My mother read the health tips downloaded.","My mother and read downloaded the health tips.","My mother read, my mother downloaded the health tips."],"a":["My mother read and downloaded the health tips."]},{"t":"mc","q":"Which is a simple sentence?","o":["I like going swimming.","I like swimming, but my sister likes running.","I stay at home because it rains.","When it rains, I read books."],"a":["I like going swimming."]},{"t":"gap","q":"Nam eats tofu. Lan eats tofu, too. → Nam ___ Lan eat tofu.","a":["and"]},{"t":"gap","q":"He washes his hands. He brushes his teeth. → He washes his hands ___ brushes his teeth.","a":["and"]},{"t":"gap","q":"My brother and I ___ outdoor activities. (love)","a":["love"]}]},{"type":"g","title":"Present simple & should (review)","vi":"Ôn tập: hiện tại đơn và lời khuyên","notes":["should / shouldn't + V: lời khuyên về sức khỏe: You should wear suncream. You shouldn't read in dim light.","Thói quen tốt dùng hiện tại đơn: She washes her hands before meals. He doesn't eat fast food."],"items":[{"t":"gap","q":"You ___ read in dim light. (không nên)","a":["shouldn't","should not"]},{"t":"gap","q":"You ___ use lip balm for chapped lips. (nên)","a":["should"]},{"t":"gap","q":"She ___ fast food. (not eat)","a":["doesn't eat","does not eat"]},{"t":"gap","q":"My grandparents ___ every morning. (exercise)","a":["exercise"]},{"t":"mc","q":"If you have sunburn, you ___ use suncream.","o":["should","shouldn't","mustn't","don't"],"a":["should"]},{"t":"mc","q":"You ___ touch your face with dirty hands.","o":["shouldn't","should","do","must"],"a":["shouldn't"]},{"t":"mc","q":"He ___ his teeth twice a day.","o":["brushes","brush","brushs","brushing"],"a":["brushes"]}]}]},{"g":7,"u":3,"title":"Community Service","vi":"Hoạt động cộng đồng","lessons":[{"type":"v","title":"Community activities – Hoạt động cộng đồng (1/2)","words":[{"w":"community activities","vi":"các hoạt động cộng đồng","ex":"Our school joins many {community activities}."},{"w":"pick up litter","vi":"nhặt rác","ex":"We {pick up litter} in the park every Sunday."},{"w":"plant trees","vi":"trồng cây","ex":"Our class {planted trees} along the road last year."},{"w":"water vegetables","vi":"tưới rau","ex":"We {water vegetables} in the school garden."},{"w":"collect old books","vi":"thu gom sách cũ","ex":"We {collect old books} for poor children."},{"w":"collect old clothes","vi":"thu gom quần áo cũ","ex":"Last month we {collected old clothes} for the flood victims."},{"w":"donate","vi":"quyên góp","ex":"We {donate} old textbooks to homeless children."},{"w":"homeless children","vi":"trẻ em vô gia cư","ex":"We gave warm clothes to {homeless children}."}]},{"type":"v","title":"Community activities – Hoạt động cộng đồng (2/2)","words":[{"w":"clean the playground","vi":"dọn dẹp sân chơi","ex":"Volunteers {cleaned the playground} yesterday."},{"w":"teach English to kids","vi":"dạy tiếng Anh cho trẻ em","ex":"My sister {teaches English to kids} in the village."},{"w":"tutor primary students","vi":"dạy kèm học sinh tiểu học","ex":"I {tutor primary students} at weekends."},{"w":"recycle plastic bottles","vi":"tái chế chai nhựa","ex":"We {recycle plastic bottles} to protect the environment."},{"w":"help old people","vi":"giúp đỡ người lớn tuổi","ex":"We {help old people} in a nursing home."},{"w":"the elderly","vi":"người lớn tuổi","ex":"We read books to {the elderly}."},{"w":"nursing home","vi":"viện dưỡng lão","ex":"Our class visited a {nursing home} last week."},{"w":"exchange used paper for notebooks","vi":"đổi giấy đã qua sử dụng để lấy vở","ex":"Students can {exchange used paper for notebooks}."}]},{"type":"g","title":"Past simple (review)","vi":"Thì quá khứ đơn (ôn tập)","notes":["(+) S + V2/V-ed · (–) S + didn't + V · (?) Did + S + V …? — Dùng cho hành động đã xảy ra và kết thúc trong quá khứ.","Dấu hiệu: yesterday, ago, last …, in the past, in + năm quá khứ.","Bất quy tắc thường gặp: go–went, give–gave, do–did, take–took, buy–bought, teach–taught, make–made, see–saw, meet–met.","Phát âm -ed: /t/ (cooked, stopped, watched); /ɪd/ (wanted, visited, needed); /d/ (played, opened, studied)."],"items":[{"t":"gap","q":"We ___ litter in the park last Sunday. (pick up)","a":["picked up"]},{"t":"gap","q":"They ___ old textbooks to homeless children last year. (donate)","a":["donated"]},{"t":"gap","q":"My class ___ a nursing home two weeks ago. (visit)","a":["visited"]},{"t":"gap","q":"She ___ English to kids last summer. (teach)","a":["taught"]},{"t":"gap","q":"We ___ any trees last week. (not plant)","a":["didn't plant","did not plant"]},{"t":"gap","q":"___ you collect old clothes for the flood victims?","a":["Did"]},{"t":"gap","q":"I ___ a lot of new friends at the volunteer camp. (make)","a":["made"]},{"t":"mc","q":"Last year we ___ 200 books to the village school.","o":["gave","give","gived","given"],"a":["gave"]},{"t":"mc","q":"___ they help the elderly yesterday?","o":["Did","Do","Does","Were"],"a":["Did"]},{"t":"mc","q":"He didn't ___ the playground.","o":["clean","cleaned","cleans","cleaning"],"a":["clean"]},{"t":"mc","q":"Which word has -ed pronounced /ɪd/?","o":["donated","picked","cleaned","helped"],"a":["donated"]},{"t":"mc","q":"Which word has -ed pronounced /t/?","o":["helped","planted","visited","played"],"a":["helped"]},{"t":"mc","q":"We recycled plastic bottles ___.","o":["last month","next month","every month","now"],"a":["last month"]}]}]},{"g":7,"u":4,"title":"Music and Arts","vi":"Âm nhạc và nghệ thuật","lessons":[{"type":"v","title":"Music – Âm nhạc","words":[{"w":"listen to music","vi":"nghe nhạc","ex":"I {listen to music} before I go to bed."},{"w":"classical music","vi":"nhạc cổ điển","ex":"My father loves {classical music}."},{"w":"play the piano","vi":"chơi đàn piano","ex":"My sister can {play the piano} very well."},{"w":"play the violin","vi":"chơi đàn vi-ô-lông","ex":"He started to {play the violin} at the age of six."},{"w":"play musical instruments","vi":"chơi các loại nhạc cụ","ex":"Can you {play musical instruments}?"},{"w":"talented","vi":"tài năng, tài giỏi","ex":"She is a {talented} young singer."},{"w":"compose music","vi":"soạn nhạc","ex":"Mozart began to {compose music} when he was five."},{"w":"talented composer","vi":"nhà soạn nhạc tài năng","ex":"Trinh Cong Son was a {talented composer}."},{"w":"famous musician","vi":"nhạc sĩ nổi tiếng","ex":"Beethoven was a {famous musician}."},{"w":"event","vi":"sự kiện","ex":"The concert was the biggest {event} of the year."},{"w":"concert","vi":"buổi hòa nhạc","ex":"We went to a rock {concert} last night."},{"w":"perform a show","vi":"trình diễn một chương trình","ex":"The students will {perform a show} at the festival."},{"w":"show","vi":"chỉ ra, cho thấy","ex":"Her drawing of her cat {shows} a lot of talent."}]},{"type":"v","title":"Arts – Nghệ thuật (1/2)","words":[{"w":"take photos","vi":"chụp ảnh","ex":"I enjoy {taking photos} of my dog."},{"w":"art gallery","vi":"phòng trưng bày mỹ thuật","ex":"There are many famous paintings in the {art gallery}."},{"w":"paint a portrait","vi":"vẽ một bức chân dung","ex":"The artist will {paint a portrait} of my mother."},{"w":"painter","vi":"họa sĩ","ex":"Van Gogh was a famous {painter}."},{"w":"paintbrush","vi":"cọ vẽ","ex":"I need a new {paintbrush}."},{"w":"painting","vi":"bức tranh màu","ex":"This {painting} is very expensive."},{"w":"drawing","vi":"bức vẽ (bút chì, bút mực)","ex":"His {drawing} of a horse is very good."},{"w":"photography","vi":"nghệ thuật nhiếp ảnh","ex":"She is interested in {photography}."},{"w":"artist","vi":"nghệ sĩ","ex":"My uncle is an {artist}."},{"w":"actor","vi":"diễn viên nam","ex":"He is a famous {actor}."}]},{"type":"v","title":"Arts – Nghệ thuật (2/2)","words":[{"w":"actress","vi":"diễn viên nữ","ex":"The {actress} won an award."},{"w":"festival","vi":"lễ hội","ex":"The music {festival} takes place in May."},{"w":"puppet theatre","vi":"nhà hát múa rối","ex":"We visited the Thang Long {puppet theatre}."},{"w":"water puppet show","vi":"buổi biểu diễn múa rối nước","ex":"Tourists love the {water puppet show}."},{"w":"exhibition","vi":"cuộc triển lãm","ex":"There is a photo {exhibition} at the museum."},{"w":"display","vi":"trưng bày","ex":"The museum {displays} old paintings."},{"w":"art collection","vi":"bộ sưu tập nghệ thuật","ex":"He has a large {art collection}."},{"w":"works of art","vi":"tác phẩm nghệ thuật","ex":"The museum has many {works of art}."},{"w":"visitor","vi":"khách tham quan","ex":"The gallery had 2,000 {visitor}s last week."}]},{"type":"g","title":"Comparisons: like, the same as, different from, (not) as … as","vi":"Các dạng so sánh","notes":["A + be + like + B (giống): My schoolbag is like your schoolbag. · the same as = like: My schoolbag is the same as your schoolbag.","A + be + different from + B (khác): My house is different from your house.","A + be + (not) as + adj + as + B (bằng / không bằng): Tom is as tall as David. This book is not as interesting as that one.","Chuyển đổi: A hơn B → B không bằng A: My bike is more expensive than your bike. → Your bike is not as expensive as my bike. · My bike isn't like your bike. → My bike is different from your bike."],"items":[{"t":"gap","q":"My schoolbag is ___ your schoolbag. (giống)","a":["like","the same as"]},{"t":"gap","q":"My house is different ___ your house.","a":["from"]},{"t":"gap","q":"Tom is as tall ___ David.","a":["as"]},{"t":"gap","q":"This book is not ___ interesting as that one.","a":["as"]},{"t":"gap","q":"My bike isn't like your bike. → My bike is ___ from your bike.","a":["different"]},{"t":"mc","q":"The blue car is faster than the red car. → The red car is ___.","o":["not as fast as the blue car","as fast as the blue car","faster than the blue car","different the blue car"],"a":["not as fast as the blue car"]},{"t":"mc","q":"This exercise is not as difficult as that exercise. → That exercise is ___ this exercise.","o":["more difficult than","as difficult as","not difficult as","the same"],"a":["more difficult than"]},{"t":"mc","q":"Your bike isn't different from my bike. → Your bike is ___ my bike.","o":["the same as","different from","not like","as"],"a":["the same as"]},{"t":"mc","q":"Her idea is ___ mine. (khác)","o":["different from","like","the same","as"],"a":["different from"]},{"t":"mc","q":"This film is ___ the film we watched last week. (giống)","o":["like","as","different","same"],"a":["like"]},{"t":"mc","q":"Lan sings as ___ as her sister.","o":["beautifully","beautiful","more beautiful","most beautifully"],"a":["beautifully"]}]}]},{"g":7,"u":5,"title":"Food and Drink","vi":"Đồ ăn và thức uống","lessons":[{"type":"v","title":"Food and dishes – Món ăn (1/2)","words":[{"w":"recipe","vi":"công thức nấu ăn","ex":"My mum has a good {recipe} for pho."},{"w":"rice","vi":"cơm, gạo","ex":"We eat {rice} every day."},{"w":"pork","vi":"thịt heo","ex":"I'd like some fried {pork}."},{"w":"beef","vi":"thịt bò","ex":"{Beef} noodle soup is my favourite dish."},{"w":"omelette","vi":"trứng ốp la","ex":"I had an {omelette} for breakfast."},{"w":"roast chicken","vi":"gà quay","ex":"We had {roast chicken} for dinner."},{"w":"fried vegetables","vi":"rau củ xào","ex":"{Fried vegetables} are healthy and tasty."},{"w":"fried tofu","vi":"đậu hũ chiên","ex":"{Fried tofu} with tomato sauce is delicious."}]},{"type":"v","title":"Food and dishes – Món ăn (2/2)","words":[{"w":"spring rolls","vi":"chả giò, nem rán","ex":"Vietnamese {spring rolls} are popular around the world."},{"w":"Vietnamese soup","vi":"canh","ex":"We often have {Vietnamese soup} with rice."},{"w":"beef noodle soup","vi":"phở bò","ex":"{Beef noodle soup} is a famous Ha Noi dish."},{"w":"broth","vi":"nước lèo, nước dùng","ex":"The {broth} of pho is made from beef bones."},{"w":"pancakes","vi":"bánh xèo, bánh kếp","ex":"I made {pancakes} for my family."},{"w":"boneless","vi":"không xương","ex":"I prefer {boneless} chicken."},{"w":"snack","vi":"bữa ăn nhẹ","ex":"I have a {snack} at 4 p.m."}]},{"type":"v","title":"Ingredients, drinks and utensils – Nguyên liệu, đồ uống, dụng cụ (1/2)","words":[{"w":"main ingredients","vi":"các nguyên liệu chính","ex":"The {main ingredients} of pho are rice noodles and beef."},{"w":"onion","vi":"hành tây","ex":"Cut the {onion} into small pieces."},{"w":"butter","vi":"bơ","ex":"Spread some {butter} on the bread."},{"w":"cheese","vi":"phô mai","ex":"I'd like a {cheese} sandwich."},{"w":"pepper","vi":"tiêu","ex":"Add a little salt and {pepper}."},{"w":"salt","vi":"muối","ex":"Don't put too much {salt} in the soup."},{"w":"sugar","vi":"đường","ex":"I don't take {sugar} in my tea."},{"w":"flour","vi":"bột","ex":"We need {flour} to make a cake."},{"w":"fish sauce","vi":"nước mắm","ex":"Vietnamese people use {fish sauce} in many dishes."},{"w":"juice","vi":"nước ép","ex":"I'd like a glass of orange {juice}."},{"w":"green tea","vi":"trà xanh","ex":"My grandpa drinks {green tea} every morning."}]},{"type":"v","title":"Ingredients, drinks and utensils – Nguyên liệu, đồ uống, dụng cụ (2/2)","words":[{"w":"mineral water","vi":"nước khoáng","ex":"A bottle of {mineral water}, please."},{"w":"winter melon juice","vi":"nước ép bí đao","ex":"{Winter melon juice} is good in hot weather."},{"w":"spoon","vi":"muỗng","ex":"Eat your soup with a {spoon}."},{"w":"tablespoon","vi":"thìa canh","ex":"Add two {tablespoon}s of sugar."},{"w":"teaspoon","vi":"muỗng cà phê","ex":"Add a {teaspoon} of salt."},{"w":"fork","vi":"cái nĩa","ex":"Use a knife and {fork} to eat steak."},{"w":"taste","vi":"nếm; hương vị","ex":"Can I {taste} the soup?"},{"w":"stew","vi":"hầm, ninh","ex":"{Stew} the beef for two hours."},{"w":"popular","vi":"phổ biến","ex":"Pho is very {popular} in Viet Nam."},{"w":"delicious","vi":"thơm ngon","ex":"This cake is {delicious}."}]},{"type":"g","title":"Quantifiers & uncountable nouns","vi":"Từ định lượng và danh từ không đếm được","notes":["some (một ít/một vài): câu khẳng định và lời mời (Would you like some tea?) · any: câu phủ định và câu hỏi (I don't have any pets. Do you have any milk?) · a lot of / lots of (nhiều): dùng cho cả 2 loại danh từ.","How many + danh từ đếm được số nhiều: How many apples do you have? · How much + danh từ không đếm được: How much water do you drink a day?","Danh từ không đếm được (không thêm -s): water, milk, tea, oil, juice, sugar, salt, pepper, cheese, butter, flour, meat, pork, beef, rice, bread, furniture, homework, information, luggage…"],"items":[{"t":"gap","q":"I have ___ pencils. (một vài)","a":["some"]},{"t":"gap","q":"Do you have ___ milk?","a":["any"]},{"t":"gap","q":"___ many apples do you have?","a":["How"]},{"t":"gap","q":"How ___ water do you drink a day?","a":["much"]},{"t":"gap","q":"There are ___ students in the yard. (nhiều)","a":["a lot of","lots of"]},{"t":"gap","q":"Would you like ___ tea?","a":["some"]},{"t":"mc","q":"How ___ eggs do we need?","o":["many","much","any","some"],"a":["many"]},{"t":"mc","q":"How ___ flour do we need?","o":["much","many","a few","any"],"a":["much"]},{"t":"mc","q":"There isn't ___ cheese in the fridge.","o":["any","some","many","a"],"a":["any"]},{"t":"mc","q":"Which noun is uncountable?","o":["butter","onion","spoon","egg"],"a":["butter"]},{"t":"mc","q":"Put ___ sugar in my tea, please.","o":["some","a","many","an"],"a":["some"]},{"t":"mc","q":"She has ___ of energy.","o":["lots","many","much","a few"],"a":["lots"]}]}]},{"g":7,"u":6,"title":"A Visit to a School","vi":"Chuyến thăm một ngôi trường","lessons":[{"type":"v","title":"School subjects and activities – Môn học và hoạt động","words":[{"w":"biology","vi":"sinh học","ex":"We learn about plants and animals in {biology}."},{"w":"information technology","vi":"công nghệ thông tin","ex":"We have {information technology} on Mondays."},{"w":"physical education","vi":"giáo dục thể chất","ex":"We play football in {physical education} lessons."},{"w":"gifted student","vi":"học sinh năng khiếu","ex":"She is a {gifted student} in maths."},{"w":"pass an entrance exam","vi":"đỗ kỳ thi đầu vào","ex":"He {passed an entrance exam} to a famous school."},{"w":"attend a school","vi":"theo học một trường","ex":"I {attend a school} near my house."},{"w":"sit for a midterm test","vi":"thi giữa kỳ","ex":"We will {sit for a midterm test} next week."},{"w":"cover three units","vi":"bao gồm ba bài học","ex":"The test will {cover three units}."},{"w":"take part in outdoor activities","vi":"tham gia hoạt động ngoài trời","ex":"Students {take part in outdoor activities} every Friday."},{"w":"study hard","vi":"học tập chăm chỉ","ex":"You must {study hard} to pass the exam."},{"w":"a visit to","vi":"chuyến thăm đến","ex":"We had {a visit to} a famous school in Ha Noi."},{"w":"celebrate an event","vi":"kỷ niệm một sự kiện","ex":"Our school {celebrates an event} every November."}]},{"type":"v","title":"Modern school facilities – Cơ sở vật chất hiện đại","words":[{"w":"computer room","vi":"phòng máy tính","ex":"We use the internet in the {computer room}."},{"w":"use the internet","vi":"sử dụng internet","ex":"Students can {use the internet} for their projects."},{"w":"school library","vi":"thư viện trường","ex":"I read newspapers in the {school library}."},{"w":"read magazines","vi":"đọc tạp chí","ex":"We {read magazines} and newspapers in the library."},{"w":"school garden","vi":"vườn trường","ex":"We grow vegetables in the {school garden}."},{"w":"grow vegetables","vi":"trồng rau","ex":"Our class {grows vegetables} in the garden."},{"w":"playground","vi":"sân chơi","ex":"The children play in the {playground}."},{"w":"gym","vi":"phòng thể dục","ex":"We exercise and have meetings in the {gym}."},{"w":"have meetings","vi":"tổ chức cuộc họp","ex":"Teachers {have meetings} in the gym."}]},{"type":"g","title":"Prepositions of time and place","vi":"Giới từ chỉ thời gian và nơi chốn","notes":["in + buổi trong ngày, tháng, năm: in the morning, in the afternoon, in the evening, in December, in 2025.","at + giờ và mốc thời gian: at 7 p.m., at noon, at night, at break time. on + thứ, ngày tháng, ngày lễ có \"Day\": on Monday, on January 18th, on Christmas Day.","Nơi chốn: in (bên trong khu vực/không gian): in the classroom, in the school garden · at (địa điểm cụ thể): at home, at school, at work, at the airport · on (trên bề mặt): on the floor, on the board, on the wall, on the table."],"items":[{"t":"gap","q":"We have English ___ Monday.","a":["on"]},{"t":"gap","q":"I get up ___ 6 a.m.","a":["at"]},{"t":"gap","q":"My birthday is ___ December.","a":["in"]},{"t":"gap","q":"We play games ___ break time.","a":["at"]},{"t":"gap","q":"My father is ___ work now.","a":["at"]},{"t":"gap","q":"There is a picture ___ the wall.","a":["on"]},{"t":"gap","q":"The students are ___ the classroom.","a":["in"]},{"t":"mc","q":"I was born ___ 2012.","o":["in","on","at","x"],"a":["in"]},{"t":"mc","q":"We often go to bed ___ night.","o":["at","in","on","x"],"a":["at"]},{"t":"mc","q":"We have a party ___ Christmas Day.","o":["on","in","at","x"],"a":["on"]},{"t":"mc","q":"The teacher wrote the words ___ the board.","o":["on","in","at","x"],"a":["on"]},{"t":"mc","q":"We will meet ___ the airport.","o":["at","in","on","x"],"a":["at"]},{"t":"mc","q":"I do my homework ___ the evening.","o":["in","on","at","x"],"a":["in"]}]}]},{"g":7,"u":7,"title":"Traffic","vi":"Giao thông","lessons":[{"type":"v","title":"Traffic rules and signs – Luật và biển báo giao thông (1/2)","words":[{"w":"traffic lights","vi":"đèn giao thông","ex":"Stop when the {traffic lights} are red."},{"w":"obey traffic rules","vi":"tuân thủ luật giao thông","ex":"Everyone must {obey traffic rules}."},{"w":"traffic jam","vi":"tắc đường, kẹt xe","ex":"We were late because of a {traffic jam}."},{"w":"road sign","vi":"biển báo giao thông","ex":"Look at the {road sign}. It says \"No cycling\"."},{"w":"no right turn","vi":"cấm rẽ phải","ex":"That sign means \"{no right turn}\"."},{"w":"no cycling","vi":"cấm đi xe đạp","ex":"You can't ride here. It's \"{no cycling}\"."},{"w":"cycle lane","vi":"làn đường cho xe đạp","ex":"Cyclists should ride in the {cycle lane}."},{"w":"school ahead","vi":"có trường học phía trước","ex":"The sign \"{school ahead}\" means drive slowly."}]},{"type":"v","title":"Traffic rules and signs & Road users and safety – Người tham gia giao thông và an toàn (1/2)","words":[{"w":"hospital ahead","vi":"có bệnh viện phía trước","ex":"Slow down! There's a \"{hospital ahead}\" sign."},{"w":"vehicle","vi":"phương tiện giao thông","ex":"A bus is a large {vehicle}."},{"w":"ride a motorbike","vi":"lái xe máy","ex":"You must be 18 to {ride a motorbike}."},{"w":"drive a car","vi":"lái ô tô","ex":"My father {drives a car} to work."},{"w":"sail a boat","vi":"lái thuyền","ex":"They {sail a boat} on the lake."},{"w":"go on foot","vi":"đi bộ","ex":"I {go on foot} because my school is near."},{"w":"travel by air","vi":"đi bằng máy bay","ex":"We {travel by air} to Phu Quoc."},{"w":"road user","vi":"người tham gia giao thông","ex":"Every {road user} must obey traffic rules."},{"w":"pedestrian","vi":"người đi bộ","ex":"{Pedestrian}s should use the pavement."},{"w":"passenger","vi":"hành khách","ex":"The bus has 40 {passenger}s."},{"w":"cyclist","vi":"người đi xe đạp","ex":"The {cyclist} is riding in the cycle lane."},{"w":"motorist","vi":"người đi xe máy, lái xe","ex":"The {motorist} stopped at the red light."},{"w":"cross the street","vi":"băng qua đường","ex":"Look left and right before you {cross the street}."},{"w":"pavement","vi":"vỉa hè","ex":"Walk on the {pavement}, not on the road."},{"w":"zebra crossing","vi":"vạch qua đường","ex":"Cross the road at the {zebra crossing}."}]},{"type":"v","title":"Road users and safety – Người tham gia giao thông và an toàn (2/2)","words":[{"w":"road safety","vi":"an toàn đường bộ","ex":"We learned about {road safety} at school."},{"w":"waste","vi":"lãng phí","ex":"Don't {waste} water."},{"w":"fasten the seatbelt","vi":"thắt dây an toàn","ex":"Always {fasten the seatbelt} in a car."},{"w":"wear a helmet","vi":"đội mũ bảo hiểm","ex":"You must {wear a helmet} on a motorbike."},{"w":"handlebars","vi":"tay lái","ex":"Hold the {handlebars} with both hands."},{"w":"be careful","vi":"hãy cẩn thận","ex":"{Be careful} when you cross the road."},{"w":"dangerous","vi":"nguy hiểm","ex":"It's {dangerous} to ride too fast."}]},{"type":"g","title":"It takes …, How far …, should","vi":"Thời gian, khoảng cách và lời khuyên","notes":["Mất bao lâu để làm gì: It takes + someone + time + to V: It takes me 15 minutes to get to school.","Hỏi khoảng cách: How far is it from A to B? → It's (about) + số + kilometres/metres + from A to B: It's about 4 kilometres from my house to school. Biến thể: What is the distance from A to B?","Lời khuyên: S + should / shouldn't + V: You should wear a helmet when driving a motorbike. You shouldn't drive your car too fast."],"items":[{"t":"gap","q":"It ___ me 15 minutes to get to school.","a":["takes"]},{"t":"gap","q":"___ far is it from your house to school?","a":["How"]},{"t":"gap","q":"It's about 4 kilometres ___ my house to school.","a":["from"]},{"t":"gap","q":"It takes him an hour ___ walk to the market.","a":["to"]},{"t":"gap","q":"You ___ wear a helmet when driving a motorbike. (nên)","a":["should"]},{"t":"gap","q":"You ___ drive your car too fast. (không nên)","a":["shouldn't","should not"]},{"t":"mc","q":"How ___ is it from Ha Noi to Hai Phong?","o":["far","long","much","many"],"a":["far"]},{"t":"mc","q":"It ___ us two hours to get there by bus.","o":["took","takes it","spent","cost"],"a":["took"]},{"t":"mc","q":"What is the ___ from your house to the bus stop?","o":["distance","far","long","length road"],"a":["distance"]},{"t":"mc","q":"Pedestrians ___ walk on the pavement.","o":["should","shouldn't","mustn't","don't"],"a":["should"]},{"t":"mc","q":"You ___ cross the street when the light is red.","o":["shouldn't","should","must","can"],"a":["shouldn't"]}]}]},{"g":7,"u":8,"title":"Films","vi":"Phim ảnh","lessons":[{"type":"v","title":"Types of films – Thể loại phim","words":[{"w":"comedy","vi":"phim hài","ex":"We laughed a lot at the {comedy}."},{"w":"documentary","vi":"phim tài liệu","ex":"This {documentary} is about real events in the war."},{"w":"fantasy","vi":"phim giả tưởng","ex":"Harry Potter is a {fantasy} film."},{"w":"science fiction film","vi":"phim khoa học viễn tưởng","ex":"Star Wars is a famous {science fiction film}."},{"w":"horror film","vi":"phim kinh dị","ex":"I don't watch {horror film}s because they're scary."},{"w":"moving","vi":"cảm động","ex":"The ending of the film was very {moving}; I cried."},{"w":"boring","vi":"nhàm chán","ex":"The film was {boring}, so I fell asleep."},{"w":"dull","vi":"tẻ nhạt","ex":"The story was long and {dull}."},{"w":"interesting","vi":"thú vị","ex":"It's an {interesting} film about animals."},{"w":"gripping","vi":"hấp dẫn","ex":"The story is {gripping} from beginning to end."},{"w":"violent","vi":"bạo lực","ex":"There is too much fighting; it's a {violent} film."},{"w":"confusing","vi":"khó hiểu","ex":"The plot was so {confusing} that I didn't understand it."},{"w":"shocking","vi":"gây sốc","ex":"The ending was {shocking}."},{"w":"frightening","vi":"đáng sợ","ex":"The horror film was really {frightening}."}]},{"type":"v","title":"Film people and other words – Người làm phim và từ khác","words":[{"w":"series","vi":"phim nhiều tập","ex":"I'm watching a Korean {series}."},{"w":"wizard","vi":"phù thủy nam","ex":"Gandalf is a famous {wizard}."},{"w":"director","vi":"đạo diễn","ex":"Who is the {director} of this film?"},{"w":"acting","vi":"diễn xuất","ex":"The {acting} in this film is excellent."},{"w":"receive good reviews","vi":"nhận được đánh giá tốt","ex":"The film {received good reviews} from critics."},{"w":"must-see","vi":"(bộ phim) nhất định phải xem","ex":"This film is a {must-see}."},{"w":"fall asleep","vi":"ngủ quên","ex":"I {fell asleep} during the film."}]},{"type":"g","title":"Although / though / however","vi":"Diễn đạt sự đối lập","notes":["Although / Though (mặc dù) + mệnh đề, nối hai ý đối lập, không dùng chung với \"but\": Although I watched the film twice, I didn't understand it. = I didn't understand the film although I watched it twice.","However (tuy nhiên): nối hai câu đối lập, dùng với dấu: \". However, …\" hoặc \"; however, …\": I watched the film twice. However, I didn't understand it.","Ba cách cùng nghĩa: I watched the film twice, but I didn't understand it."],"items":[{"t":"gap","q":"___ I watched the film twice, I didn't understand it. (mặc dù)","a":["Although","Though"]},{"t":"gap","q":"I watched the film twice. ___, I didn't understand it. (tuy nhiên)","a":["However"]},{"t":"gap","q":"The film was long; ___, it was very interesting.","a":["however"]},{"t":"mc","q":"___ the film was boring, we watched it until the end.","o":["Although","However","But","Because"],"a":["Although"]},{"t":"mc","q":"It was a horror film. ___, I wasn't afraid.","o":["However","Although","Though","Because"],"a":["However"]},{"t":"mc","q":"Which sentence is WRONG?","o":["Although it rained, but we went out.","Although it rained, we went out.","It rained, but we went out.","It rained. However, we went out."],"a":["Although it rained, but we went out."]},{"t":"mc","q":"I didn't like the film ___ it got good reviews.","o":["though","however","but","so"],"a":["though"]},{"t":"mc","q":"The acting was great; ___, the story was dull.","o":["however","although","though","because"],"a":["however"]}]}]},{"g":7,"u":9,"title":"Festivals around the World","vi":"Lễ hội trên thế giới","lessons":[{"type":"v","title":"Types of festivals – Các lễ hội","words":[{"w":"Cannes Film Festival","vi":"lễ hội phim Cannes","ex":"Many interesting films are shown at the {Cannes Film Festival}."},{"w":"Christmas","vi":"lễ Giáng sinh","ex":"People give presents to each other at {Christmas}."},{"w":"give presents","vi":"tặng quà","ex":"We {give presents} to our friends at Christmas."},{"w":"Easter","vi":"lễ Phục sinh","ex":"Children look for chocolate eggs at {Easter}."},{"w":"Easter Bunny","vi":"thỏ Phục sinh","ex":"The {Easter Bunny} brings eggs for children."},{"w":"paint eggs","vi":"vẽ lên trứng","ex":"Children {paint eggs} at Easter."},{"w":"Tulip Festival","vi":"lễ hội hoa tulip","ex":"The {Tulip Festival} takes place in the Netherlands."},{"w":"tulip float","vi":"xe hoa tulip diễu hành","ex":"We watched a beautiful {tulip float}."},{"w":"Mid-Autumn Festival","vi":"lễ hội Trung thu","ex":"Children carry lanterns at the {Mid-Autumn Festival}."},{"w":"mooncake","vi":"bánh trung thu","ex":"We eat {mooncake}s at the Mid-Autumn Festival."},{"w":"perform a lion dance","vi":"biểu diễn múa lân","ex":"They {perform a lion dance} in the street."},{"w":"Halloween","vi":"lễ hội hóa trang","ex":"Children wear scary costumes at {Halloween}."},{"w":"candy apple","vi":"kẹo táo","ex":"I bought a {candy apple} at the festival."},{"w":"carve pumpkins","vi":"điêu khắc bí ngô","ex":"We {carve pumpkins} for Halloween."}]},{"type":"v","title":"Festival activities – Hoạt động lễ hội","words":[{"w":"wear traditional costumes","vi":"mặc trang phục truyền thống","ex":"People {wear traditional costumes} at the festival."},{"w":"watch a parade","vi":"xem diễu hành","ex":"We {watched a parade} in the city centre."},{"w":"watch fireworks display","vi":"xem bắn pháo hoa","ex":"We {watch fireworks display} at New Year."},{"w":"watch folk dances","vi":"xem múa dân gian","ex":"Tourists love to {watch folk dances}."},{"w":"perform folk dances","vi":"trình diễn múa dân gian","ex":"Students {perform folk dances} at the school festival."},{"w":"carry","vi":"mang, vác","ex":"They {carry} lanterns around the village."},{"w":"twins","vi":"cặp sinh đôi","ex":"The {twins} wear the same costumes."},{"w":"performance","vi":"buổi biểu diễn","ex":"The music {performance} was amazing."}]},{"type":"g","title":"Yes / No questions","vi":"Câu hỏi Có / Không","notes":["Hiện tại đơn (V/Vs/Ves) → Do / Does + S + V? She watches TV every night. → Does she watch TV every night?","Quá khứ đơn (V2/V-ed) → Did + S + V? My sister held a party last week. → Did your sister hold a party last week?","Có am/is/are/was/were/can/will/should → đảo các từ này lên đầu câu: They are playing football. → Are they playing football? Tom will travel to the USA. → Will Tom travel to the USA?"],"items":[{"t":"gap","q":"She watches TV every night. → ___ she watch TV every night?","a":["Does"]},{"t":"gap","q":"They are playing football at the park. → ___ they playing football at the park?","a":["Are"]},{"t":"gap","q":"Tom will travel to the USA next month. → ___ Tom travel to the USA next month?","a":["Will"]},{"t":"gap","q":"They learned a lot about the past. → ___ they learn a lot about the past?","a":["Did"]},{"t":"gap","q":"You can watch lion dances at the festival. → ___ I watch lion dances at the festival?","a":["Can"]},{"t":"gap","q":"My sister held a party last week. → Did your sister ___ a party last week?","a":["hold"]},{"t":"mc","q":"___ you go to the festival last year?","o":["Did","Do","Were","Are"],"a":["Did"]},{"t":"mc","q":"___ she like Halloween?","o":["Does","Do","Is","Did"],"a":["Does"]},{"t":"mc","q":"___ they at the parade yesterday?","o":["Were","Did","Was","Do"],"a":["Were"]},{"t":"mc","q":"___ we wear traditional costumes? – Yes, we should.","o":["Should","Do","Are","Did"],"a":["Should"]},{"t":"mc","q":"Did Tom ___ mooncakes last night?","o":["eat","ate","eats","eating"],"a":["eat"]}]}]},{"g":7,"u":10,"title":"Energy Sources","vi":"Các nguồn năng lượng","lessons":[{"type":"v","title":"Types of energy sources – Các loại nguồn năng lượng","words":[{"w":"solar energy","vi":"năng lượng mặt trời","ex":"{Solar energy} comes from the sun's heat."},{"w":"wind energy","vi":"năng lượng gió","ex":"{Wind energy} comes from winds and breezes."},{"w":"hydro energy","vi":"năng lượng nước","ex":"Water provides people with {hydro energy}."},{"w":"nuclear energy","vi":"năng lượng hạt nhân","ex":"{Nuclear energy} can be dangerous."},{"w":"renewable energy","vi":"năng lượng tái tạo được","ex":"Solar and wind energy are {renewable energy} sources."},{"w":"non-renewable energy","vi":"năng lượng không tái tạo được","ex":"Oil and coal are {non-renewable energy} sources."},{"w":"natural gas","vi":"khí đốt tự nhiên","ex":"We cook with {natural gas}."},{"w":"coal","vi":"than đá","ex":"{Coal} pollutes the air."},{"w":"run out","vi":"hết, cạn kiệt","ex":"Oil will {run out} one day."},{"w":"solar panels","vi":"tấm pin năng lượng mặt trời","ex":"We put {solar panels} on the roof."},{"w":"produce energy","vi":"tạo ra năng lượng","ex":"Solar panels {produce energy} from the sun."},{"w":"change A to B","vi":"chuyển A thành B","ex":"Solar panels {change} the sun's heat {to} electricity."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"reduce the use of electricity","vi":"giảm việc sử dụng điện","ex":"We should {reduce the use of electricity}."},{"w":"provide","vi":"cung cấp","ex":"Water {provides} people with hydro energy."},{"w":"cheap","vi":"rẻ","ex":"Solar energy is clean and {cheap}."},{"w":"expensive","vi":"đắt tiền","ex":"Nuclear power plants are very {expensive}."},{"w":"rely on","vi":"phụ thuộc vào","ex":"We {rely on} coal for electricity."},{"w":"electrical appliances","vi":"các thiết bị điện","ex":"Turn off {electrical appliances} when you don't use them."},{"w":"low energy light bulb","vi":"bóng đèn năng lượng thấp","ex":"Use a {low energy light bulb} to save energy."},{"w":"save energy","vi":"tiết kiệm năng lượng","ex":"We can {save energy} by turning off the lights."},{"w":"protect the environment","vi":"bảo vệ môi trường","ex":"Renewable energy helps {protect the environment}."},{"w":"turn off","vi":"tắt (thiết bị)","ex":"{Turn off} the lights when you leave the room."},{"w":"replace","vi":"thay thế","ex":"{Replace} old bulbs with low energy ones."}]},{"type":"g","title":"Present continuous (review)","vi":"Thì hiện tại tiếp diễn (ôn tập)","notes":["(+) S + am/is/are + V-ing · (–) S + am/is/are + not + V-ing · (?) Am/Is/Are + S + V-ing?","Dấu hiệu: now, right now, at the moment, at present, today, Look! / Listen!"],"items":[{"t":"gap","q":"My family ___ solar panels on the roof now. (put)","a":["is putting"]},{"t":"gap","q":"Look! The wind turbines ___ very fast. (turn)","a":["are turning"]},{"t":"gap","q":"We ___ electricity at the moment. (not use)","a":["aren't using","are not using"]},{"t":"gap","q":"___ your father replacing the light bulbs now?","a":["Is"]},{"t":"gap","q":"At present, many countries ___ more renewable energy. (use)","a":["are using"]},{"t":"mc","q":"Listen! Someone ___ the piano.","o":["is playing","plays","play","played"],"a":["is playing"]},{"t":"mc","q":"They ___ about energy sources right now.","o":["are talking","talk","talks","talked"],"a":["are talking"]},{"t":"mc","q":"___ you saving energy at the moment?","o":["Are","Do","Is","Does"],"a":["Are"]},{"t":"mc","q":"She ___ TV now. She's doing her homework.","o":["isn't watching","doesn't watch","not watching","watches"],"a":["isn't watching"]}]}]},{"g":7,"u":11,"title":"Travelling in the Future","vi":"Đi lại trong tương lai","lessons":[{"type":"v","title":"Future transport – Phương tiện tương lai (1/2)","words":[{"w":"means of transport","vi":"phương tiện đi chuyển","ex":"The bus is a popular {means of transport}."},{"w":"fly a flying car","vi":"bay bằng ô tô bay","ex":"One day we will {fly a flying car} to school."},{"w":"bamboo-copter","vi":"chong chóng tre","ex":"Doraemon's {bamboo-copter} can fly anywhere."},{"w":"convenient","vi":"tiện lợi","ex":"A bamboo-copter is very {convenient}."},{"w":"comfortable","vi":"thoải mái","ex":"The new train seats are very {comfortable}."},{"w":"driverless car","vi":"ô tô không người lái","ex":"A {driverless car} can drive itself."},{"w":"ride a skyTran","vi":"đi tàu điện trên không","ex":"People will {ride a skyTran} above the city."},{"w":"bullet train","vi":"tàu siêu tốc hình viên đạn","ex":"The {bullet train} is very fast."}]},{"type":"v","title":"Future transport – Phương tiện tương lai (2/2)","words":[{"w":"hyperloop","vi":"tàu siêu tốc đường ống","ex":"We will travel by {hyperloop} in the future."},{"w":"solar-powered ship","vi":"tàu chạy bằng năng lượng mặt trời","ex":"A {solar-powered ship} doesn't pollute the sea."},{"w":"teleporter","vi":"máy dịch chuyển tức thời","ex":"With a {teleporter}, you can travel in a second."},{"w":"solowheel","vi":"xe điện một bánh","ex":"A {solowheel} is small and easy to carry."},{"w":"run on","vi":"chạy bằng (năng lượng)","ex":"Cars will {run on} solar energy in the future."},{"w":"eco-friendly","vi":"thân thiện với môi trường","ex":"Bicycles are {eco-friendly}."},{"w":"safe","vi":"an toàn","ex":"Driverless cars will be very {safe}."},{"w":"not cause pollution","vi":"không gây ô nhiễm","ex":"Electric cars {do not cause pollution}."}]},{"type":"g","title":"Future simple & possessive pronouns","vi":"Tương lai đơn và đại từ sở hữu","notes":["Tương lai đơn: (+) S + will + V · (–) S + will not (won't) + V · (?) Will + S + V? Dùng cho việc sẽ xảy ra hoặc dự đoán. Dấu hiệu: next, tomorrow, soon, in the future, in/by + năm tương lai (in 2030, by 2050).","Tính từ sở hữu → đại từ sở hữu: my–mine, your–yours, their–theirs, our–ours, her–hers, his–his, its–its. That book is my book. → That book is mine.","Tính từ sở hữu luôn có danh từ đi sau; đại từ sở hữu luôn đứng một mình."],"items":[{"t":"gap","q":"We ___ to school by hyperloop. (travel)","a":["will travel","'ll travel"]},{"t":"gap","q":"We ___ to school by motorbike in the future. (not go)","a":["won't go","will not go"]},{"t":"gap","q":"___ we use bullet trains by 2050?","a":["Will"]},{"t":"gap","q":"That book is my book. → That book is ___.","a":["mine"]},{"t":"gap","q":"Your bike is blue. Her bike is pink. → Your bike is blue. ___ is pink.","a":["Hers"]},{"t":"gap","q":"This is his house. → This house is ___.","a":["his"]},{"t":"gap","q":"These are her shoes. → These shoes are ___.","a":["hers"]},{"t":"mc","q":"In 2050, people ___ flying cars.","o":["will drive","drove","drive","are driving"],"a":["will drive"]},{"t":"mc","q":"This car is ___. (của chúng tôi)","o":["ours","our","us","we"],"a":["ours"]},{"t":"mc","q":"Is this ticket ___? (của bạn)","o":["yours","your","you","you're"],"a":["yours"]},{"t":"mc","q":"Which word is a signal for the future simple?","o":["soon","yesterday","ago","last year"],"a":["soon"]}]}]},{"g":7,"u":12,"title":"English-speaking Countries","vi":"Các nước nói tiếng Anh","lessons":[{"type":"v","title":"Places and attractions – Địa điểm và điểm tham quan","words":[{"w":"English-speaking country","vi":"đất nước nói tiếng Anh","ex":"Canada is an {English-speaking country}."},{"w":"attraction","vi":"điểm thu hút","ex":"The Eiffel Tower is a famous tourist {attraction}."},{"w":"amazing view","vi":"phong cảnh tuyệt vời","ex":"There is an {amazing view} from the mountain."},{"w":"go penguin watching","vi":"đi xem chim cánh cụt","ex":"In New Zealand you can {go penguin watching}."},{"w":"island","vi":"hòn đảo","ex":"New Zealand is an {island} country."},{"w":"coastline","vi":"đường bờ biển","ex":"Australia has a very long {coastline}."},{"w":"castle","vi":"lâu đài","ex":"Edinburgh {castle} is very old."},{"w":"be famous for","vi":"nổi tiếng về","ex":"Scotland {is famous for} its ancient castles."},{"w":"Australian","vi":"người Úc","ex":"Many {Australian}s love surfing."},{"w":"be native to","vi":"có nguồn gốc từ","ex":"Kangaroos {are native to} Australia."},{"w":"have tattoos","vi":"có hình xăm","ex":"Many Maori people {have tattoos}."},{"w":"Scottish kilt","vi":"váy truyền thống của đàn ông Scotland","ex":"He wore a {Scottish kilt} at the festival."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"unique","vi":"độc nhất vô nhị","ex":"The kangaroo is a {unique} animal."},{"w":"local people","vi":"người dân địa phương","ex":"The {local people} are very friendly."},{"w":"the capital city of","vi":"thủ đô của","ex":"Canberra is {the capital city of} Australia."},{"w":"the symbol of","vi":"biểu tượng của","ex":"The kangaroo is {the symbol of} Australia."},{"w":"the kingdom of","vi":"vương quốc","ex":"{The kingdom of} Thailand is very famous."},{"w":"take a boat ride","vi":"đi chuyến du thuyền","ex":"We {took a boat ride} on the river."},{"w":"tower","vi":"tòa tháp","ex":"We climbed to the top of the {tower}."},{"w":"Statue of Liberty","vi":"tượng Nữ thần Tự do","ex":"The {Statue of Liberty} is in New York."},{"w":"shining beach","vi":"bãi biển đầy nắng","ex":"We relaxed on a {shining beach}."},{"w":"historic town","vi":"thị trấn cổ có tầm quan trọng lịch sử","ex":"York is a {historic town} in England."},{"w":"rich in","vi":"giàu về","ex":"Carrots are {rich in} vitamin A."}]},{"type":"g","title":"Articles: a / an / the","vi":"Mạo từ","notes":["a / an (một) + danh từ số ít: an trước nguyên âm u, e, o, a, i (an apple, an island, an attraction); a trước các từ còn lại (a book, a country, a kangaroo).","the đứng trước: so sánh nhất (the laziest, the most intelligent); vật duy nhất (the Earth, the Moon, the Sun, the air, the environment, the Eiffel Tower); danh từ nhắc lại lần thứ 2 (I have a dog. The dog is big.).","the + tên quốc gia đặc biệt: the USA, the UK, the Philippines, the Netherlands; the + chủ ngữ có giới từ vị trí phía sau: The pen on the table is mine."],"items":[{"t":"gap","q":"Australia has ___ amazing coastline.","a":["an"]},{"t":"gap","q":"He is ___ most intelligent student in my class.","a":["the"]},{"t":"gap","q":"I have a dog. ___ dog is big and yellow.","a":["The"]},{"t":"gap","q":"My uncle lives in ___ USA.","a":["the"]},{"t":"gap","q":"A kangaroo is ___ unique animal.","a":["a"]},{"t":"mc","q":"___ Earth goes around the Sun.","o":["The","A","An","x"],"a":["The"]},{"t":"mc","q":"Scotland is ___ country in the UK.","o":["a","an","the","x"],"a":["a"]},{"t":"mc","q":"New Zealand is ___ island country.","o":["an","a","the","x"],"a":["an"]},{"t":"mc","q":"___ house next to my house is very large.","o":["The","A","An","x"],"a":["The"]},{"t":"mc","q":"We should protect ___ environment.","o":["the","a","an","x"],"a":["the"]}]}]}];